def _clean_keys(saved):
    keys = dict(DEFAULT_KEYS)
    if isinstance(saved, dict):
        for action, k in saved.items():
            if action in keys and isinstance(k, str) and k.upper() in ALLOWED_KEYS:
                keys[action] = k.upper()
    if len(set(keys.values())) != len(keys):  # two actions on the same key -> use defaults
        keys = dict(DEFAULT_KEYS)
    return keys


def key_code(action):
    return getattr(e, "KEY_" + LETTERS[action])


def label(action):
    return "+".join([m.capitalize() for m in MOD_ORDER if m in MODIFIERS] + [LETTERS[action]])


