VERSION = "AI_W_2.5.8"

# ---------------------------------------------------------------------------
# Updates. The program can look for a newer version and install it from a button in the Shift+M menu.
# Put the web address of your version.json here (see RELEASING.txt). Left empty = no update button.
# ---------------------------------------------------------------------------
UPDATE_MANIFEST_URL = "https://raw.githubusercontent.com/TheInvisGuy/All-in-one-AI-window/main/version.json"
UPDATE_FILE = "ai_window_update.py"  # the packaged program keeps a downloaded update next to itself under this name
PIN_FILE = "ai_window_update.pin"    # packaged program: says "run the file above even if it is OLDER" (see below)
VERSION_RE = re.compile(r'^VERSION = "(AI_W_[0-9][0-9.]*)"', re.M)
# The version built into the packaged program. When the program runs a downloaded ai_window_update.py instead,
# VERSION above is that file's version, so the packaged program passes its own version on in this variable.
BUILTIN_VERSION = os.environ.get("AIW_BUILTIN_VERSION") or VERSION


def version_tuple(text):
    """'AI_W_2.5.8' -> (2, 5, 8), so versions can be compared."""
    nums = re.findall(r"\d+", str(text))
    return tuple(int(n) for n in nums) or (0,)


def _valid_release(entry):
    """One entry of the manifest (version / url / sha256 / notes), or None if it looks wrong."""
    try:
        version = str(entry.get("version", ""))
        url = str(entry.get("url", ""))
        sha = str(entry.get("sha256", "")).lower()
    except AttributeError:
        return None
    if (not re.fullmatch(r"AI_W_\d+(\.\d+)*", version) or not url.startswith("https://")
            or not re.fullmatch(r"[0-9a-f]{64}", sha)):
        return None
    return {"version": version, "url": url, "sha256": sha, "notes": str(entry.get("notes", ""))[:300]}


def fetch_update_info(manifest_url):
    """Ask the update address for the newest version and the list of all versions (runs in a background
    thread). Returns a dict: state is 'available', 'uptodate' or 'error', plus a message, plus 'versions'
    (every version you can install, newest first)."""
    try:
        resp = requests.get(manifest_url, timeout=8, headers={"Cache-Control": "no-cache"})
        resp.raise_for_status()
        data = resp.json()
        latest = _valid_release(data)
        extra = [_valid_release(item) for item in (data.get("versions") or [])]
    except Exception as err:  # noqa: BLE001  (no internet, bad answer, ...)
        return {"state": "error", "message": f"Could not check for updates ({err.__class__.__name__})."}
    if latest is None:
        return {"state": "error", "message": "The update information is not valid, so it was ignored."}
    releases = {latest["version"]: latest}  # the main entry first, so it wins if a version is listed twice
    for item in extra:
        if item and item["version"] not in releases:
            releases[item["version"]] = item
    versions = sorted(releases.values(), key=lambda r: version_tuple(r["version"]), reverse=True)
    if version_tuple(latest["version"]) <= version_tuple(VERSION):
        return {"state": "uptodate", "message": f"{VERSION}: you have the newest version.", "versions": versions}
    return {"state": "available", "version": latest["version"], "url": latest["url"], "sha256": latest["sha256"],
            "notes": latest["notes"], "message": "", "versions": versions}


def download_update(info):
    """Download the new program file and check it before it is used. Returns the file's bytes.
    Raises RuntimeError (with a message that can be shown) if anything is wrong."""
    try:
        resp = requests.get(info["url"], timeout=30, stream=True)
        resp.raise_for_status()
        if not str(resp.url).startswith("https://"):
            raise RuntimeError("The download was not over a secure (https) connection, so it was not used.")
        chunks, size = [], 0
        for chunk in resp.iter_content(65536):
            size += len(chunk)
            if size > 12_000_000:
                raise RuntimeError("The update file is too big, so it was not used.")
            chunks.append(chunk)
        raw = b"".join(chunks)
    except requests.RequestException as err:
        raise RuntimeError(f"Download failed ({err.__class__.__name__}).") from err
    if hashlib.sha256(raw).hexdigest() != info["sha256"]:
        raise RuntimeError("The downloaded file does not match its checksum, so it was NOT installed.")
    try:
        text = raw.decode("utf-8")
        compile(text, UPDATE_FILE, "exec")
    except (UnicodeDecodeError, SyntaxError, ValueError):
        raise RuntimeError("The downloaded file is not a working program, so it was NOT installed.") from None
    found = VERSION_RE.search(text)
    if not found or found.group(1) != info["version"]:
        raise RuntimeError(f"The downloaded file is not version {info['version']}, so it was NOT installed.")
    return raw


def install_update(raw, version=""):
    """Store the chosen program version. A plain ai_window.py is replaced (the old one is kept as .bak); the
    packaged program can't change its own code, so it goes next to it as ai_window_update.py instead.
    (If that version is OLDER than the one built into the program, a small .pin file tells the program to
    run it anyway.)"""
    if getattr(sys, "frozen", False):
        target = os.path.join(_APP_DIR, UPDATE_FILE)
        pin = os.path.join(_APP_DIR, PIN_FILE)
        try:
            if version and version_tuple(version) <= version_tuple(BUILTIN_VERSION):
                with open(pin, "w", encoding="utf-8") as f:
                    f.write(f"{BUILTIN_VERSION}\n{version}\n")  # built-in version, chosen version
            elif os.path.exists(pin):
                os.remove(pin)
        except OSError:
            pass
    else:
        target = os.path.abspath(__file__)
        try:
            shutil.copy2(target, target + ".bak")
        except OSError:
            pass
    tmp = target + ".new"
    with open(tmp, "wb") as f:
        f.write(raw)
    os.replace(tmp, target)
    return target


def run_downloaded_update_if_newer():
    """Packaged program only: if a newer ai_window_update.py was downloaded, run that instead of the
    code built into the program (it uses the libraries that are packed inside)."""
    if not getattr(sys, "frozen", False) or os.environ.get("AIW_RUNNING_UPDATE"):
        return
    path = os.path.join(_APP_DIR, UPDATE_FILE)
    try:
        with open(path, "r", encoding="utf-8") as f:
            found = VERSION_RE.search(f.read())
    except (OSError, UnicodeDecodeError):
        return
    if not found:
        return
    if version_tuple(found.group(1)) <= version_tuple(VERSION):
        # Not newer than what is built in (e.g. after rebuilding the program) - unless you picked this older
        # version on purpose. The pin only counts for the exact program it was made for.
        try:
            with open(os.path.join(_APP_DIR, PIN_FILE), "r", encoding="utf-8") as f:
                pinned = f.read().split()
        except OSError:
            return
        if pinned != [VERSION, found.group(1)]:
            return
    os.environ["AIW_RUNNING_UPDATE"] = "1"
    os.environ["AIW_BUILTIN_VERSION"] = VERSION  # (so the update knows which version is built in)
    import runpy
    try:
        runpy.run_path(path, run_name="__main__")
    except SystemExit:
        raise
    except Exception:  # noqa: BLE001
        traceback.print_exc()
        try:  # the update does not start: put it aside and use the version built into the program
            os.replace(path, path + ".bad")
        except OSError:
            pass
        os.environ.pop("AIW_RUNNING_UPDATE", None)
        os.environ.pop("AIW_BUILTIN_VERSION", None)
        return
    sys.exit(0)


# How much bigger than "normal" the whole interface is (1.0 = normal). Set at start-up, see _init_scaling.
UI_SCALE = [1.0]


def S(n):
    """A size in pixels, multiplied by the interface scale (so the program is not tiny on 4K screens)."""
    v = int(round(n * UI_SCALE[0]))
    return v if n <= 0 else max(1, v)


SCALE_CHOICES = ["Auto", "100%", "125%", "150%", "175%", "200%", "250%", "300%"]
PIRATE_SIDES = ["Left", "Middle", "Right"]
COLOR_KEYS = ("bg_color", "header_color", "button_color")

# ---- save slots ------------------------------------------------------------
# A slot remembers EVERY setting you can configure (AI, look, window, keys, typing, screenshot, fun), and
# has a name, a short description and a photo. Switching slots swaps all of it in one click.
# Only the interface size stays the same for all slots: it depends on this computer's screen and only
# applies after a restart.
SLOT_FIELDS = tuple(k for k in DEFAULTS if k not in ("slots", "active_slot", "ui_scale"))
# the settings the slots held in the first version (older config files only have these in their slots)
LEGACY_SLOT_FIELDS = ("provider", "providers", "screenshot_prompt", "persona", "custom_persona",
                      "auto_prompt_enabled", "auto_prompt", "bg_color", "header_color", "button_color")
MAX_SLOTS = 8
# colors the three starting slots come with: (background, top bar, send button)
SLOT_LOOKS = [THEMES["Default purple"], THEMES["Ocean"], THEMES["Sunset"]]


def make_slot(source, name, description="", photo=""):
    """A new slot holding a copy of the AI + color settings found in `source` (a config dict)."""
    slot = {"name": name, "description": description, "photo": photo}
    for k in SLOT_FIELDS:
        slot[k] = copy.deepcopy(source[k])
    return slot


def default_slots():
    slots = []
    for n, look in enumerate(SLOT_LOOKS, start=1):
        src = {k: copy.deepcopy(DEFAULTS[k]) for k in SLOT_FIELDS}
        src["bg_color"], src["header_color"], src["button_color"] = look
        slots.append(make_slot(src, f"Slot {n}"))
    return slots


DEFAULTS["slots"] = default_slots()
DEFAULTS["active_slot"] = 0


def sync_active_slot(cfg):
    """Copy the live AI/color settings into the active slot, so a slot always has your latest changes."""
    slots, i = cfg.get("slots"), cfg.get("active_slot")
    if isinstance(slots, list) and isinstance(i, int) and 0 <= i < len(slots):
        for k in SLOT_FIELDS:
            slots[i][k] = copy.deepcopy(cfg[k])


def apply_slot(cfg, i):
    """Make slot i the active one: its settings become the live settings."""
    cfg["active_slot"] = i
    for k in SLOT_FIELDS:
        cfg[k] = copy.deepcopy(cfg["slots"][i][k])


def _clean_slots(raw, cfg):
    """Check the slots read from the config file (fixing anything odd). No slots yet (an older config)?
    Then the three starting slots all begin as the settings you were already using."""
    slots = []
    if isinstance(raw, list):
        for s in raw[:MAX_SLOTS]:
            if not isinstance(s, dict):
                continue
            # anything a slot is missing (e.g. a slot saved by an older version) starts as your current setting
            base = {k: copy.deepcopy(DEFAULTS[k] if k in LEGACY_SLOT_FIELDS else cfg[k]) for k in SLOT_FIELDS}
            name = str(s.get("name", "")).strip()[:24] or f"Slot {len(slots) + 1}"
            photo = s.get("photo") if isinstance(s.get("photo"), str) else ""
            slot = make_slot(base, name, str(s.get("description", ""))[:70], photo)
            for k in SLOT_FIELDS:
                if k not in s:
                    continue
                v, d = s[k], DEFAULTS[k]
                if k == "providers":
                    if isinstance(v, dict):
                        for pname, vals in v.items():
                            if pname in slot["providers"] and isinstance(vals, dict):
                                slot["providers"][pname].update({a: str(b) for a, b in vals.items()
                                                                 if a in ("api_key", "model")})
                elif k == "keys":
                    slot[k] = _clean_keys(v)
                elif k == "modifiers":
                    mods = [m for m in v if m in MOD_GROUPS] if isinstance(v, list) else []
                    slot[k] = mods or list(DEFAULT_MODIFIERS)
                elif k in COLOR_KEYS:
                    if isinstance(v, str) and HEX_RE.match(v):
                        slot[k] = v
                elif k == "provider":
                    if v in PROVIDERS:
                        slot[k] = v
                elif k == "persona":
                    if v in PERSONAS:
                        slot[k] = v
                elif isinstance(d, bool):
                    if isinstance(v, bool):
                        slot[k] = v
                elif isinstance(d, int):
                    if isinstance(v, int) and not isinstance(v, bool):
                        slot[k] = v
                elif isinstance(d, float):
                    if isinstance(v, (int, float)) and not isinstance(v, bool):
                        slot[k] = float(v)
                elif isinstance(d, str):
                    if isinstance(v, str):
                        slot[k] = v
                elif isinstance(d, list):
                    if isinstance(v, list):
                        slot[k] = copy.deepcopy(v)
            slots.append(slot)
    if not slots:
        for n, look in enumerate(SLOT_LOOKS, start=1):
            src = copy.deepcopy(cfg)
            if n > 1:  # slots 2 and 3 get their own look, everything else is what you use now
                src["bg_color"], src["header_color"], src["button_color"] = look
            slots.append(make_slot(src, f"Slot {n}"))
    return slots


