# Settings-menu theme (Shift+M): deep purple background, bright purple buttons
MENU_BG = "#8400DB"           # the menu background
MENU_FG = "#ffffff"
MENU_BUTTON = "#52008F"       # buttons and the top strip: a deeper purple so they stand out on the background
MENU_BUTTON_ACTIVE = "#A23CFF"  # button while hovered / pressed
MENU_TAB = "#6A00B3"          # tabs that are not selected, scrollbar track
MENU_HINT = "#ead9fb"         # small help texts (light purple, readable on the background)
MENU_ERR = "#ffc2cc"          # error messages
MENU_QUIT = "#b3263e"         # 'Quit app' stays red on purpose (it is the destructive button)
TYPE_DELAY = 0.05  # seconds between typed letters (Shift+B)
MAX_IMAGE_BYTES = 4_500_000  # screenshots bigger than this are refused (providers limit ~5 MB)
HEX_RE = re.compile(r"^#[0-9a-fA-F]{6}$")
# inline markdown: ***bold italic***, **bold**, `code`, *italic*
INLINE_RE = re.compile(r"(\*\*\*[^*\n]+?\*\*\*|\*\*[^*\n]+?\*\*|`[^`\n]+`"
                       r"|(?<![\w*])\*[^*\s][^*\n]*?(?<!\s)\*(?![\w*]))")
LINK_RE = re.compile(r"\[([^\]\n]+)\]\((https?://[^)\s]+)\)")


def luminance(hex_color):
    r, g, b = (int(hex_color[i:i + 2], 16) / 255 for i in (1, 3, 5))
    return 0.2126 * r + 0.7152 * g + 0.0722 * b


def shade(hex_color, amount):
    """Mix a color with white (amount > 0) or black (amount < 0)."""
    target, a = (255, amount) if amount > 0 else (0, -amount)
    parts = [int(int(hex_color[i:i + 2], 16) * (1 - a) + target * a) for i in (1, 3, 5)]
    return "#%02x%02x%02x" % tuple(parts)


def load_config():
    cfg = copy.deepcopy(DEFAULTS)
    saved = {}
    try:
        with open(CONFIG_FILE, "r", encoding="utf-8") as f:
            loaded = json.load(f)
        saved = loaded if isinstance(loaded, dict) else {}
        for k, v in saved.items():
            if k in ("slots", "active_slot"):
                continue  # handled below
            if k == "providers" and isinstance(v, dict):
                for name, vals in v.items():
                    if name in cfg["providers"] and isinstance(vals, dict):
                        cfg["providers"][name].update(vals)
            elif k == "keys":
                cfg["keys"] = _clean_keys(v)
            elif k == "modifiers":
                mods = [m for m in v if m in MOD_GROUPS] if isinstance(v, list) else []
                cfg["modifiers"] = mods or list(DEFAULT_MODIFIERS)
            else:
                cfg[k] = v
    except (FileNotFoundError, json.JSONDecodeError):
        pass
    if cfg["provider"] not in PROVIDERS:
        cfg["provider"] = DEFAULTS["provider"]
    cfg["slots"] = _clean_slots(saved.get("slots"), cfg)
    try:
        active = int(saved.get("active_slot", 0))
    except (TypeError, ValueError):
        active = 0
    apply_slot(cfg, min(max(active, 0), len(cfg["slots"]) - 1))  # the active slot decides the live settings
    return cfg


def save_config(cfg):
    sync_active_slot(cfg)
    try:
        with open(CONFIG_FILE, "w", encoding="utf-8") as f:
            json.dump(cfg, f, indent=2)
    except OSError:
        pass


def choice_box(parent, var, values, width):
    """Pick-from-a-list box with arrow buttons. A drop-down list can stay open and block the
    hotkeys if you click away from it, so this one deliberately has no pop-up."""
    return ttk.Spinbox(parent, textvariable=var, values=list(values), state="readonly", width=width, wrap=True)


def load_slot_photo(path, size=128):
    """Read a picture file, crop it to a square and return it as a small base64 PNG: (data, error text)."""
    try:
        import io
        from PIL import Image
        img = Image.open(path).convert("RGBA")
        side = min(img.size)
        left, top = (img.width - side) // 2, (img.height - side) // 2
        img = img.crop((left, top, left + side, top + side)).resize((size, size), Image.LANCZOS)
        buf = io.BytesIO()
        img.save(buf, format="PNG", optimize=True)
        return base64.b64encode(buf.getvalue()).decode(), ""
    except ImportError:
        pass  # no Pillow: try Tk itself below
    except Exception as err:  # noqa: BLE001
        return "", f"Could not read that picture ({err.__class__.__name__})."
    try:
        src = tk.PhotoImage(file=path)
        f = max(1, max(src.width(), src.height()) // size)
        small = src.subsample(f) if f > 1 else src
        tmp = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
        tmp.close()
        small.write(tmp.name, format="png")
        with open(tmp.name, "rb") as fh:
            data = base64.b64encode(fh.read()).decode()
        os.unlink(tmp.name)
        return data, ""
    except (tk.TclError, OSError):
        return "", "Could not read that picture. Use a PNG or GIF (or install Pillow: sudo apt install python3-pil)."


def _raise_for_status(resp):
    if not resp.ok:
        raise RuntimeError(f"HTTP {resp.status_code}: {resp.text[:300]}")


def _openai_messages(history):
    out = []
    for m in history:
        if m.get("image"):
            out.append({"role": m["role"], "content": [
                {"type": "text", "text": m["content"]},
                {"type": "image_url", "image_url": {"url": "data:image/png;base64," + m["image"]}}]})
        else:
            out.append({"role": m["role"], "content": m["content"]})
    return out


def call_openai_style(url, key, model, history, system=""):
    messages = _openai_messages(history)
    if system:
        messages.insert(0, {"role": "system", "content": system})
    resp = requests.post(url, headers={"Authorization": f"Bearer {key}"},
                         json={"model": model, "messages": messages}, timeout=60)
    _raise_for_status(resp)
    return resp.json()["choices"][0]["message"]["content"]


def _claude_messages(history):
    out = []
    for m in history:
        if m.get("image"):
            out.append({"role": m["role"], "content": [
                {"type": "image", "source": {"type": "base64", "media_type": "image/png",
                                             "data": m["image"]}},
                {"type": "text", "text": m["content"]}]})
        else:
            out.append({"role": m["role"], "content": m["content"]})
    return out


def call_claude(key, model, history, system=""):
    body = {"model": model, "max_tokens": 1024, "messages": _claude_messages(history)}
    if system:
        body["system"] = system
    resp = requests.post("https://api.anthropic.com/v1/messages",
                         headers={"x-api-key": key, "anthropic-version": "2023-06-01"},
                         json=body, timeout=60)
    _raise_for_status(resp)
    return "".join(b.get("text", "") for b in resp.json()["content"] if b.get("type") == "text")


def call_gemini(key, model, history, system=""):
    contents = []
    for m in history:
        parts = [{"text": m["content"]}]
        if m.get("image"):
            parts.insert(0, {"inline_data": {"mime_type": "image/png", "data": m["image"]}})
        contents.append({"role": "user" if m["role"] == "user" else "model", "parts": parts})
    body = {"contents": contents}
    if system:
        body["system_instruction"] = {"parts": [{"text": system}]}
    resp = requests.post(
        f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent",
        headers={"x-goog-api-key": key}, json=body, timeout=60)
    _raise_for_status(resp)
    data = resp.json()
    cands = data.get("candidates") or []
    if not cands:
        raise RuntimeError(f"Gemini returned no answer ({data.get('promptFeedback') or data})"[:300])
    cand = cands[0]
    parts = (cand.get("content") or {}).get("parts") or []
    text = "".join(p.get("text", "") for p in parts if not p.get("thought"))
    if not text.strip():
        raise RuntimeError(f"Gemini returned an empty answer (finishReason: {cand.get('finishReason')}).")
    return text


def call_ollama(model, history, system=""):
    messages = [{"role": "system", "content": system}] if system else []
    for m in history:
        msg = {"role": m["role"], "content": m["content"]}
        if m.get("image"):
            msg["images"] = [m["image"]]  # needs a vision model (llava, llama3.2-vision, ...)
        messages.append(msg)
    try:
        resp = requests.post("http://localhost:11434/api/chat",
                             json={"model": model, "messages": messages, "stream": False},
                             timeout=300)
    except requests.exceptions.ConnectionError:
        raise RuntimeError("Can't reach Ollama. Install it from https://ollama.com and make sure "
                           "it is running (try:  ollama serve).")
    _raise_for_status(resp)
    return resp.json()["message"]["content"]


def history_to_prompt(history):
    if len(history) == 1:
        return history[0]["content"]
    lines = ["Conversation so far:"]
    for m in history[:-1]:
        lines.append(("User: " if m["role"] == "user" else "Assistant: ") + m["content"])
    lines += ["", "Now answer this latest message (reply with the answer only):", history[-1]["content"]]
    return "\n".join(lines)


def call_cli(provider, model, history, system=""):
    """Run an official CLI (claude / gemini) that is already logged in to your account."""
    tool = CLI_TOOLS[provider]
    if history and history[-1].get("image"):
        raise RuntimeError("Screenshots can't be sent through the login (command-line) options. "
                           "Switch to an API provider (Claude, ChatGPT, Gemini, Grok) or an Ollama "
                           "vision model in Shift+M > AI.")
    if not shutil.which(tool["exe"]):
        raise RuntimeError(f"'{tool['exe']}' is not installed. {tool['install']}")
    os.makedirs(CLI_WORKDIR, exist_ok=True)  # empty folder so the tool has no project files to touch
    cmd = [tool["exe"]] + list(tool["base"])
    if model and model != "default":
        cmd += [tool["model_flag"], model]
    prompt = history_to_prompt(history)
    if system:  # the command-line tools have no system field, so put it in front of the question
        prompt = f"Instructions for how to answer: {system}\n\n{prompt}"
    if prompt.startswith("-"):  # don't let the question be read as a command-line option
        prompt = " " + prompt
    if tool["prompt_flag"]:
        cmd.append(tool["prompt_flag"])
    cmd.append(prompt)
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=180,
                           cwd=CLI_WORKDIR, stdin=subprocess.DEVNULL)
    except subprocess.TimeoutExpired:
        raise RuntimeError(f"{tool['exe']} took too long (over 3 minutes).")
    if r.returncode != 0:
        detail = (r.stderr or r.stdout or "").strip()[:300]
        raise RuntimeError(f"{tool['exe']} failed: {detail or 'unknown error'}. "
                           f"If you are not logged in, run  {tool['exe']}  once in a terminal and sign in.")
    return r.stdout.strip()


def ask_ai(provider, key, model, history, system=""):
    if provider in CLI_TOOLS:
        return call_cli(provider, model, history, system)
    if provider == "Ollama (local)":
        return call_ollama(model, history, system)
    if provider == "ChatGPT":
        return call_openai_style("https://api.openai.com/v1/chat/completions", key, model, history, system)
    if provider == "Grok":
        return call_openai_style("https://api.x.ai/v1/chat/completions", key, model, history, system)
    if provider == "Claude":
        return call_claude(key, model, history, system)
    if provider == "Gemini":
        return call_gemini(key, model, history, system)
    raise RuntimeError(f"Unknown provider: {provider}")


# ---------------------------------------------------------------------------
# Clipboard / selection helpers (work on X11 and Wayland)
# ---------------------------------------------------------------------------
ON_WAYLAND = bool(os.environ.get("WAYLAND_DISPLAY"))
IS_GNOME = "GNOME" in os.environ.get("XDG_CURRENT_DESKTOP", "").upper()


def _capture(cmd, timeout=1.5):
    if not shutil.which(cmd[0]):
        return None
    try:
        r = subprocess.run(cmd, capture_output=True, timeout=timeout)
    except (subprocess.TimeoutExpired, OSError):
        return None
    return r.stdout.decode("utf-8", "replace") if r.returncode == 0 else None


def read_selection():
    """Return the text currently highlighted anywhere (the PRIMARY selection)."""
    x11 = [["xclip", "-selection", "primary", "-o"], ["xsel", "-p", "-o"]]
    wl = [["wl-paste", "--primary", "--no-newline"]]
    order = x11 + wl if (IS_GNOME or not ON_WAYLAND) else wl + x11
    for cmd in order:
        out = _capture(cmd)
        if out and out.strip():
            return out.strip()
    return ""


def _push(cmd, text):
    if not shutil.which(cmd[0]):
        return
    try:
        p = subprocess.Popen(cmd, stdin=subprocess.PIPE,
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        p.communicate(text.encode("utf-8"), timeout=2)
    except (subprocess.TimeoutExpired, OSError):
        pass


SCREENSHOT_HELP = (
    "No working screenshot tool found. Install one:\n"
    "  any desktop (Wayland or X11):  sudo apt install flameshot\n"
    "  X11 only:                      sudo apt install maim\n"
    "  Sway / Hyprland:               sudo apt install grim slurp\n"
    "  KDE:                           sudo apt install kde-spectacle")

# Asks the desktop's screenshot portal (GNOME/KDE/...) for an interactive area screenshot.
PORTAL_SCRIPT = r"""
import os
import gi
gi.require_version("Gio", "2.0")
from gi.repository import Gio, GLib
bus = Gio.bus_get_sync(Gio.BusType.SESSION, None)
loop = GLib.MainLoop()
out = {}
def on_response(conn, sender, path, iface, signal, params, data):
    code, res = params.unpack()
    out["code"], out["uri"], out["res"] = code, res.get("uri"), res
    loop.quit()
token = "aiwindow%d" % GLib.get_monotonic_time()
req = "/org/freedesktop/portal/desktop/request/%s/%s" % (bus.get_unique_name()[1:].replace(".", "_"), token)
bus.signal_subscribe("org.freedesktop.portal.Desktop", "org.freedesktop.portal.Request", "Response",
                     req, None, Gio.DBusSignalFlags.NONE, on_response, None)
bus.call_sync("org.freedesktop.portal.Desktop", "/org/freedesktop/portal/desktop",
              "org.freedesktop.portal.Screenshot", "Screenshot",
              GLib.Variant("(sa{sv})", ("", {"interactive": GLib.Variant("b", os.environ.get("AIW_INTERACTIVE", "1") == "1"),
                                             "handle_token": GLib.Variant("s", token)})),
              None, Gio.DBusCallFlags.NONE, -1, None)
GLib.timeout_add_seconds(120, loop.quit)
loop.run()
if out.get("code") == 0 and out.get("uri"):
    print(out["uri"])
else:
    import sys
    print("portal answered: code=%s result=%s" % (out.get("code"), out.get("res")), file=sys.stderr)
"""

LAST_CAPTURE_INFO = [""]  # what the last tool reported (shown when a capture is 'cancelled')
BROKEN_SCREENSHOT_TOOLS = set()  # tools that crashed once this session are skipped afterwards


SCREENSHOT_TOOLS = ["auto", "gnome-screenshot", "flameshot", "portal", "spectacle", "grim", "maim",
                    "scrot", "import"]


def _tool_available(name, ignore_broken=False, mode="area"):
    if name in BROKEN_SCREENSHOT_TOOLS and not ignore_broken:
        return False
    if name == "grim":  # slurp (the area picker) is only needed for 'select area'
        return bool(shutil.which("grim") and (mode == "full" or shutil.which("slurp")))
    if name == "portal":
        return bool(shutil.which("python3"))
    return bool(shutil.which(name))


def _run_screenshot_tool(tool, path, mode="area"):
    """Run one tool. Returns PNG bytes, or None if the user cancelled. Raises RuntimeError on failure.
    mode 'area' = let the user drag a rectangle, 'full' = grab the whole screen without any window.
    A tool that quits in under a second without an image never showed a selector -> failure."""
    area = mode == "area"
    t0 = time.time()

    def quick_exit(detail):
        if area and time.time() - t0 < 1.0:
            raise RuntimeError(f"{detail} (exited immediately, no selector shown)")

    if tool == "flameshot":
        cmd = ["flameshot", "gui", "--raw"] if area else ["flameshot", "full", "--raw"]
        r = subprocess.run(cmd, capture_output=True, timeout=120 if area else 30)
        if r.stdout.startswith(b"\x89PNG"):
            return r.stdout
        err = r.stderr.decode("utf-8", "replace").strip()
        LAST_CAPTURE_INFO[0] = f"flameshot exit {r.returncode}, no image. {err[:150]}"
        if not area:
            raise RuntimeError(err[:200] or "flameshot returned no image")
        quick_exit(f"flameshot exit {r.returncode} {err[:100]}")
        if err and "cancel" not in err.lower() and r.returncode not in (0, 1):
            raise RuntimeError(err[:200])
        return None
    if tool == "portal":
        env = dict(os.environ, AIW_INTERACTIVE="1" if area else "0")
        r = subprocess.run(["python3", "-c", PORTAL_SCRIPT], capture_output=True, text=True,
                           timeout=130 if area else 40, env=env)
        uri = r.stdout.strip()
        LAST_CAPTURE_INFO[0] = f"portal exit {r.returncode}, no image. {r.stderr.strip()[-150:]}"
        if not uri:
            if not area:
                raise RuntimeError((r.stderr.strip().splitlines() or ["the desktop refused the screenshot"])[-1][:200])
            quick_exit(f"portal exit {r.returncode} {r.stderr.strip()[-100:]}")
            if r.returncode != 0 or r.stderr.strip():
                raise RuntimeError((r.stderr.strip().splitlines() or ["portal failed"])[-1][:200])
            return None
        from urllib.parse import unquote, urlparse
        shot = unquote(urlparse(uri).path)
        with open(shot, "rb") as f:
            data = f.read()
        try:
            os.remove(shot)  # the portal saved a copy in Pictures; we only needed it temporarily
        except OSError:
            pass
        return data
    if tool == "grim":
        if area:
            sel = subprocess.run(["slurp"], capture_output=True, text=True, timeout=120)
            if sel.returncode != 0 or not sel.stdout.strip():
                LAST_CAPTURE_INFO[0] = "slurp: no area selected"
                return None
            cmd = ["grim", "-g", sel.stdout.strip(), path]
        else:
            cmd = ["grim", path]
    else:
        cmd = {
            "area": {
                "maim": ["maim", "-s", path],
                "scrot": ["scrot", "-s", path],
                "import": ["import", path],
                "gnome-screenshot": ["gnome-screenshot", "-a", "-f", path],
                "spectacle": ["spectacle", "-b", "-n", "-r", "-o", path],
            },
            "full": {
                "maim": ["maim", path],
                "scrot": ["scrot", path],
                "import": ["import", "-window", "root", path],
                "gnome-screenshot": ["gnome-screenshot", "-f", path],
                "spectacle": ["spectacle", "-b", "-n", "-f", "-o", path],
            },
        }[mode][tool]
    r = subprocess.run(cmd, capture_output=True, text=True, timeout=120 if area else 30)
    if os.path.exists(path) and os.path.getsize(path) > 0:
        with open(path, "rb") as f:
            return f.read()
    err = (r.stderr or "").strip()
    LAST_CAPTURE_INFO[0] = f"{tool} exit {r.returncode}, no image file was created."
    if err:
        raise RuntimeError(err[:200])
    if not area:
        raise RuntimeError(f"{tool} did not create an image")
    quick_exit(f"{tool} exit {r.returncode}")
    return None  # cancelled (Esc)


def grant_portal_screenshot():
    """Store 'this program may take silent screenshots' in the desktop portal's permission store
    (same thing as:  flatpak permission-set screenshot screenshot "" yes).  Returns True if stored."""
    if not shutil.which("gdbus"):
        return False
    try:
        r = subprocess.run(
            ["gdbus", "call", "--session",
             "--dest", "org.freedesktop.impl.portal.PermissionStore",
             "--object-path", "/org/freedesktop/impl/portal/PermissionStore",
             "--method", "org.freedesktop.impl.portal.PermissionStore.SetPermission",
             "screenshot", "true", "screenshot", "", "['yes']"],
            capture_output=True, text=True, timeout=10)
    except (subprocess.TimeoutExpired, OSError):
        return False
    return r.returncode == 0


def capture_screen(mode="area", preferred="auto"):
    """Take a screenshot. mode: 'area' (drag a rectangle) or 'full' (whole screen, no windows).
    preferred: 'auto' tries the installed tools in order and skips any that fail; a tool name uses
    ONLY that tool (so it can't open a second screenshot app). Returns PNG bytes, or None if cancelled."""
    if preferred != "auto":
        if preferred not in SCREENSHOT_TOOLS or not _tool_available(preferred, ignore_broken=True, mode=mode):
            raise RuntimeError(f"The screenshot tool '{preferred}' is not installed (or can't do this). "
                               "Pick another one in Shift+M > Screenshot, or choose 'auto'.")
        tools = [preferred]
        if preferred == "portal" and mode == "full" and not ON_WAYLAND:
            # on X11 the desktop may refuse silent portal screenshots, so try other tools too
            # (never on Wayland: maim / scrot / import only return a BLACK image there)
            tools += [n for n in ["maim", "scrot", "import", "flameshot", "spectacle", "gnome-screenshot"]
                      if _tool_available(n, mode=mode)]
    else:
        if ON_WAYLAND:
            names = (["gnome-screenshot", "flameshot", "portal"] if IS_GNOME
                     else ["grim", "spectacle", "flameshot", "gnome-screenshot", "portal"])
        else:
            names = ["maim", "scrot", "import", "flameshot", "spectacle", "gnome-screenshot", "portal"]
        tools = [n for n in names if _tool_available(n, mode=mode)]
        if not tools:
            raise RuntimeError(SCREENSHOT_HELP)

    tmpdir = tempfile.mkdtemp(prefix="ai-window-")
    path = os.path.join(tmpdir, "shot.png")
    errors = []
    try:
        for tool in tools:
            try:
                return _run_screenshot_tool(tool, path, mode)  # PNG bytes, or None when cancelled
            except subprocess.TimeoutExpired:
                raise RuntimeError("The screenshot took too long (timed out).")
            except (RuntimeError, OSError) as err:
                if tool == "portal" and mode == "full" and preferred == "portal" and ON_WAYLAND:
                    # the desktop refuses SILENT screenshots from this program until the permission
                    # is stored once in the portal's permission store: grant it, then try again
                    if grant_portal_screenshot():
                        time.sleep(1.0)  # give the portal a moment to notice the new permission
                        try:
                            return _run_screenshot_tool("portal", path, "full")
                        except subprocess.TimeoutExpired:
                            raise RuntimeError("The screenshot took too long (timed out).")
                        except (RuntimeError, OSError) as err2:
                            raise RuntimeError(f"portal: {err2} (the permission was granted but the "
                                               "desktop still refused; log out and in once and try again)")
                    raise RuntimeError(f"portal: {err} (could not grant the screenshot permission; "
                                       "gdbus is missing?)")
                if len(tools) == 1 and preferred != "auto":
                    raise RuntimeError(f"{tool}: {err}")
                if preferred == "auto":
                    BROKEN_SCREENSHOT_TOOLS.add(tool)
                errors.append(f"{tool}: {err}")
        raise RuntimeError("; ".join(errors)[:400] + "\n" + SCREENSHOT_HELP)
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)


def fit_png(png):
    """Return PNG bytes small enough to send (shrinks with Pillow if installed), or None."""
    if len(png) <= MAX_IMAGE_BYTES:
        return png
    try:
        import io
        from PIL import Image
        img = Image.open(io.BytesIO(png))
        for _ in range(6):
            img = img.resize((int(img.width * 0.75), int(img.height * 0.75)), Image.LANCZOS)
            buf = io.BytesIO()
            img.save(buf, "PNG", optimize=True)
            if buf.tell() <= MAX_IMAGE_BYTES:
                return buf.getvalue()
    except Exception:  # noqa: BLE001  (Pillow missing or image unreadable)
        pass
    return None


# ---------------------------------------------------------------------------
# Keyboard layouts for typing (Shift+B). Maps a character to (key, modifier).
# Characters that are not in the table are typed by pasting that one character.
# ---------------------------------------------------------------------------
def _k(name):
    return getattr(e, name)


def _build_layouts():
    common = {" ": (_k("KEY_SPACE"), ""), "\t": (_k("KEY_TAB"), "")}
    other = dict(common)
    for ch in "abcdefghijklmnopqrstuvwxyz":
        code = _k("KEY_" + ch.upper())
        common[ch] = (code, "")
        common[ch.upper()] = (code, "shift")
    for d in "0123456789":
        common[d] = (_k("KEY_" + d), "")

    us = dict(common)
    for ch, d in zip("!@#$%^&*()", "1234567890"):
        us[ch] = (_k("KEY_" + d), "shift")
    for plain, shifted, name in [("-", "_", "MINUS"), ("=", "+", "EQUAL"), ("[", "{", "LEFTBRACE"),
                                 ("]", "}", "RIGHTBRACE"), ("\\", "|", "BACKSLASH"),
                                 (";", ":", "SEMICOLON"), ("'", '"', "APOSTROPHE"),
                                 ("`", "~", "GRAVE"), (",", "<", "COMMA"), (".", ">", "DOT"),
                                 ("/", "?", "SLASH")]:
        us[plain] = (_k("KEY_" + name), "")
        us[shifted] = (_k("KEY_" + name), "shift")

    es = dict(common)  # Spanish / Catalan keyboard
    for ch, d in zip('!"\u00b7$%&/()=', "1234567890"):
        es[ch] = (_k("KEY_" + d), "shift")
    es.update({
        ",": (_k("KEY_COMMA"), ""), ";": (_k("KEY_COMMA"), "shift"),
        ".": (_k("KEY_DOT"), ""), ":": (_k("KEY_DOT"), "shift"),
        "-": (_k("KEY_SLASH"), ""), "_": (_k("KEY_SLASH"), "shift"),
        "'": (_k("KEY_MINUS"), ""), "?": (_k("KEY_MINUS"), "shift"),
        "\u00a1": (_k("KEY_EQUAL"), ""), "\u00bf": (_k("KEY_EQUAL"), "shift"),
        "+": (_k("KEY_RIGHTBRACE"), ""), "*": (_k("KEY_RIGHTBRACE"), "shift"),
        "<": (_k("KEY_102ND"), ""), ">": (_k("KEY_102ND"), "shift"),
        "\u00f1": (_k("KEY_SEMICOLON"), ""), "\u00d1": (_k("KEY_SEMICOLON"), "shift"),
        "\u00e7": (_k("KEY_BACKSLASH"), ""), "\u00c7": (_k("KEY_BACKSLASH"), "shift"),
        "@": (_k("KEY_2"), "altgr"), "#": (_k("KEY_3"), "altgr"), "|": (_k("KEY_1"), "altgr"),
        "\\": (_k("KEY_GRAVE"), "altgr"), "[": (_k("KEY_LEFTBRACE"), "altgr"),
        "]": (_k("KEY_RIGHTBRACE"), "altgr"), "{": (_k("KEY_APOSTROPHE"), "altgr"),
        "}": (_k("KEY_BACKSLASH"), "altgr"),
    })
    return {"us": us, "es": es, "other": other}


LAYOUTS = _build_layouts()
INJECT_KEYS = sorted(
    {code for table in LAYOUTS.values() for code, _ in table.values()}
    | {e.KEY_LEFTSHIFT, e.KEY_RIGHTALT, e.KEY_LEFTCTRL, e.KEY_V, e.KEY_ENTER, e.KEY_SPACE, e.KEY_TAB})


def detect_layout():
    """Return 'us', 'es' or 'other' for the keyboard layout currently active."""
    def normalize(name):
        base, _, variant = name.strip().partition("+")
        if base == "us" and not variant:
            return "us"
        if base == "es" and variant in ("", "cat"):
            return "es"
        return "other"

    pattern = r"\('xkb',\s*'([^']+)'\)"
    if IS_GNOME:
        for key in ("mru-sources", "sources"):
            out = _capture(["gsettings", "get", "org.gnome.desktop.input-sources", key]) or ""
            m = re.search(pattern, out)
            if m:
                return normalize(m.group(1))
    out = _capture(["setxkbmap", "-query"]) or ""
    lay = re.search(r"^layout:\s*(\S+)", out, re.M)
    if lay:
        var = re.search(r"^variant:\s*(\S+)", out, re.M)
        first = lay.group(1).split(",")[0]
        variant = var.group(1).split(",")[0] if var else ""
        return normalize(first + ("+" + variant if variant else ""))
    return "other"


# ---------------------------------------------------------------------------
# Global hotkey engine (evdev grab + uinput forwarding)
# ---------------------------------------------------------------------------
SETUP_HELP = """
Cannot access the keyboard / uinput devices. One-time setup:

  sudo apt install python3-evdev python3-requests python3-tk wl-clipboard xclip
  sudo usermod -aG input $USER
  echo 'KERNEL=="uinput", MODE="0660", GROUP="input", OPTIONS+="static_node=uinput"' | sudo tee /etc/udev/rules.d/99-uinput.rules
  echo uinput | sudo tee /etc/modules-load.d/uinput.conf
  sudo modprobe uinput
  sudo udevadm control --reload-rules && sudo udevadm trigger

Then LOG OUT and log back in (so the new group applies) and run the app again.
"""


def find_keyboards():
    devs = []
    for path in evdev.list_devices():
        try:
            d = evdev.InputDevice(path)
        except OSError:
            continue
        keys = d.capabilities().get(e.EV_KEY, [])
        if (e.KEY_Z in keys and e.KEY_ENTER in keys and e.KEY_LEFTSHIFT in keys
                and not d.name.startswith("ai-window")):
            devs.append(d)
        else:
            d.close()
    return devs


class HotkeyEngine:
    """Grabs the keyboard(s), forwards every key to a virtual keyboard, and
    swallows only the configured hotkeys."""

    def __init__(self, actions, on_quit):
        self.actions = actions  # evdev key code -> callable (must be quick)
        self.on_quit = on_quit
        self.pressed = set()
        self.swallowed = set()
        self.devices = []
        self.injector = None
        self.lock = threading.Lock()
        self.paused = False  # True while you are typing in one of our text boxes (lets you type capitals)
        self.always_on = set()  # hotkey codes that still work while paused (the Z toggle)
        self.typing_cancel = threading.Event()

    # -- logic ---------------------------------------------------------------
    def modifiers_down(self):
        return {name for name, codes in MOD_GROUPS.items() if self.pressed & codes}

    def handle_key(self, code, value):
        """Return True if the event must be swallowed (not forwarded)."""
        with self.lock:
            if value == 1:
                self.pressed.add(code)
            elif value == 0:
                self.pressed.discard(code)

            if value == 1 and code == e.KEY_ESC:
                self.typing_cancel.set()  # Esc stops Shift+B typing (Esc itself still goes through)

            if value == 1 and code == e.KEY_Q and self.modifiers_down() == {"ctrl", "alt", "shift"}:
                self.swallowed.add(code)
                self.on_quit()
                return True

            if (value == 1 and code in self.actions
                    and (not self.paused or code in self.always_on)
                    and self.modifiers_down() == MODIFIERS):
                self.swallowed.add(code)
                self.actions[code]()
                return True

            if code in self.swallowed:
                if value == 0:
                    self.swallowed.discard(code)
                return True
            return False

    # -- devices ---------------------------------------------------------------
    def start(self):
        devs = find_keyboards()
        if not devs:
            raise RuntimeError("No readable keyboard found.")
        try:
            self.injector = UInput({e.EV_KEY: INJECT_KEYS}, name="ai-window-injector")
        except Exception as err:  # noqa: BLE001
            raise RuntimeError(f"Cannot create virtual keyboard: {err}")
        time.sleep(0.3)  # let the desktop notice the new virtual device
        self.devices = devs
        for d in devs:
            threading.Thread(target=self._run_device, args=(d,), daemon=True).start()

    def _run_device(self, dev):
        try:
            ui = UInput.from_device(dev, name="ai-window-forward")
        except Exception as err:  # noqa: BLE001
            print(f"[hotkeys] cannot clone {dev.name}: {err}")
            return

        # Wait until no key is held (e.g. the Enter that launched us), otherwise
        # that key could get "stuck" when we grab the device.
        t0 = time.time()
        try:
            while dev.active_keys() and time.time() - t0 < 5:
                time.sleep(0.05)
            dev.grab()
        except OSError as err:
            print(f"[hotkeys] cannot grab {dev.name}: {err} (is another copy running?)")
            ui.close()
            return

        print(f"[hotkeys] listening on: {dev.name}")
        try:
            for ev in dev.read_loop():
                if ev.type == e.EV_KEY:
                    if ev.value == 2:  # auto-repeat is generated by the desktop itself
                        continue
                    if self.handle_key(ev.code, ev.value):
                        continue
                    ui.write(e.EV_KEY, ev.code, ev.value)
                elif ev.type == e.EV_SYN:
                    ui.syn()
        except OSError:
            pass  # device unplugged
        finally:
            try:
                dev.ungrab()
            except OSError:
                pass
            ui.close()

    def wait_modifiers_released(self, timeout=2.0):
        t0 = time.time()
        while self.modifiers_down() and time.time() - t0 < timeout:
            time.sleep(0.02)

    def send_paste(self):
        """Type Ctrl+V into whatever app has focus."""
        self.wait_modifiers_released()
        time.sleep(0.05)
        for code, val in ((e.KEY_LEFTCTRL, 1), (e.KEY_V, 1), (e.KEY_V, 0), (e.KEY_LEFTCTRL, 0)):
            self.injector.write(e.EV_KEY, code, val)
            self.injector.syn()
            time.sleep(0.01)

    def _tap(self, code, mod):
        inj = self.injector
        mods = {"shift": [e.KEY_LEFTSHIFT], "altgr": [e.KEY_RIGHTALT]}.get(mod, [])
        for m in mods:
            inj.write(e.EV_KEY, m, 1)
            inj.syn()
            time.sleep(0.003)
        inj.write(e.EV_KEY, code, 1)
        inj.syn()
        inj.write(e.EV_KEY, code, 0)
        inj.syn()
        for m in reversed(mods):
            inj.write(e.EV_KEY, m, 0)
            inj.syn()

    def type_text(self, text, layout, newline_mode, fallback, delay=TYPE_DELAY):
        """Type text one character at a time. Returns True if any character needed `fallback`."""
        table = LAYOUTS.get(layout, LAYOUTS["other"])
        self.typing_cancel.clear()
        self.wait_modifiers_released()
        time.sleep(0.15)
        used_fallback = False
        for ch in text:
            if self.typing_cancel.is_set():
                break
            if ch == "\r":
                continue
            if ch == "\n":
                entry = {"Space": (e.KEY_SPACE, ""),
                         "Enter": (e.KEY_ENTER, "")}.get(newline_mode, (e.KEY_ENTER, "shift"))
            else:
                entry = table.get(ch)
            if entry:
                self._tap(*entry)
            else:
                fallback(ch)
                used_fallback = True
            time.sleep(delay)
        return used_fallback

    def shutdown(self):
        for d in self.devices:
            try:
                d.ungrab()
            except Exception:  # noqa: BLE001
                pass


# ---------------------------------------------------------------------------
# The window
# ---------------------------------------------------------------------------
class AIWindow:
    def __init__(self):
        self.cfg = load_config()
        LETTERS.update(self.cfg["keys"])
        MODIFIERS.clear()
        MODIFIERS.update(self.cfg["modifiers"])
        self.history = []
        self.last_answer = ""
        self.settings_win = None
        self.slots_win = None        # the save-slots menu (Shift+M)
        self.slot_edit_win = None    # the editor for one slot
        self._open_popups = set()    # menu windows that are open right now
        self._slots_close = None     # functions that close the three menus above (None = not open)
        self._edit_cancel = None
        self._settings_save = None
        self.horse = None        # the spinning horse window (None = not shown)
        self.pirate = None       # the pirate at the bottom of the screen (None = not shown)
        self.update_state = "idle"   # idle / checking / uptodate / available / installing / installed / error
        self.update_info = None      # what the update address said about the newest version
        self.update_versions = []    # every version the update address offers (newest first)
        self.update_pick = ""        # the version chosen in the version picker
        self.update_text = ""        # message shown in the menu
        self.update_checked_at = 0.0
        self._update_announced = ""
        self._update_row = None      # (menu window, frame) of the update line in the slots menu
        self.scare_job = None    # the timer that fires the next random jump scare
        self.scare_win = None    # the jump scare window while it is on screen
        self._scare_cache = None
        self.q = queue.Queue()  # worker threads -> Tk main thread

        # ---------- main window ----------
        self.has_focus = False
        self.root = tk.Tk()
        self._init_scaling()
        self.root.title(self.cfg["title"])
        self.root.attributes("-topmost", True)
        self.root.protocol("WM_DELETE_WINDOW", self.hide)
        self.root.withdraw()

        self.header = tk.Frame(self.root, bg=ACCENT)
        self.header.pack(fill="x")
        self.title_label = tk.Label(self.header, bg=ACCENT, fg="white", font=("Sans", 10, "bold"))
        self.title_label.pack(side="left", padx=8, pady=4)
        self.provider_label = tk.Label(self.header, bg=ACCENT, fg="#e0d8ff", font=("Sans", 8))
        self.provider_label.pack(side="right", padx=8)

        self.chat = tk.Text(self.root, wrap="word", bd=0, padx=10, pady=8, font=("Sans", 10),
                            height=4, width=20, state="disabled", highlightthickness=0)

        # the input row is packed BEFORE the chat area, so it always keeps its space
        self.bottom = tk.Frame(self.root)
        self.bottom.pack(side="bottom", fill="x", padx=8, pady=8)
        self.entry = tk.Entry(self.bottom, relief="flat", font=("Sans", 10))
        self.entry.pack(side="left", fill="x", expand=True, ipady=6)
        self.entry.bind("<Return>", self.send)
        self.send_btn = tk.Button(self.bottom, text="Send", relief="flat",
                                  command=self.send, padx=10)
        self.send_btn.pack(side="right", padx=(6, 0))
        self.chat.pack(fill="both", expand=True)

        self.apply_theme()
        self.update_title()

        # click anywhere in the window to type; Esc hides it
        for w in (self.header, self.title_label, self.provider_label):
            w.bind("<Button-1>", self._drag_start)
            w.bind("<B1-Motion>", self._drag_move)
            w.bind("<ButtonRelease-1>", self._drag_end)
        self.chat.bind("<ButtonRelease-1>",
                       lambda ev: None if self.chat.tag_ranges("sel") else self.entry.focus_set())
        self.root.bind("<Escape>", lambda ev: self.hide())

        self.append("sys", f"{label('ask')} ask about highlighted text · {label('screenshot')} / {label('screenshot2')} screenshot · "
                           f"{label('paste')} paste answer · {label('type')} type answer · "
                           f"{label('settings')} menu · {label('quit')} quit · Esc hide\n\n")

        self.apply_geometry()
        self.apply_opacity()
        self._frameless_state = None  # None = not checked yet, "ok" or "fallback"
        self.apply_frameless()
        self.root.after(40, self._poll)

        # ---------- global hotkeys ----------
        self.engine = HotkeyEngine(self._build_actions(), on_quit=lambda: self.ui(self.quit_app))
        self.engine.always_on = {key_code("toggle")}
        try:
            self.engine.start()
        except RuntimeError as err:
            print(f"\nERROR: {err}\n{SETUP_HELP}")
            self.root.destroy()
            sys.exit(1)
        self.root.after(1500, self.send_auto_prompt)
        self.root.after(900, self.apply_fun)
        self.root.after(5000, self.check_update_async)  # quietly look for a newer version

    def _build_actions(self):
        def thread(fn):
            return lambda: threading.Thread(target=fn, daemon=True).start()

        return {
            key_code("toggle"): lambda: self.ui(self.toggle_window),
            key_code("settings"): lambda: self.ui(self.toggle_settings),
            key_code("ask"): thread(self.ask_selection),
            key_code("screenshot"): thread(self.ask_screenshot),
            key_code("screenshot2"): thread(lambda: self.ask_screenshot(2)),
            key_code("paste"): thread(self.paste_answer),
            key_code("type"): thread(self.type_answer),
            key_code("quit"): lambda: self.ui(self.quit_app),
        }

    def apply_keybinds(self):
        """Use the keys/modifiers from self.cfg right now (no restart needed)."""
        LETTERS.update(self.cfg["keys"])
        MODIFIERS.clear()
        MODIFIERS.update(self.cfg["modifiers"])
        with self.engine.lock:
            self.engine.actions = self._build_actions()
            self.engine.always_on = {key_code("toggle")}

    # ---------- thread plumbing ----------
    def ui(self, fn, *args):
        """Run fn(*args) on the Tk main thread (safe to call from any thread)."""
        self.q.put((fn, args))

    def _typing_here(self):
        """True while the keyboard focus is in a text box of this program (the chat box, or a field in a
        menu). Only then are the hotkeys paused, so capital letters can be typed there. Having the
        window merely 'in front' (for example right after a menu closed) does NOT pause them."""
        try:
            w = self.root.focus_get()  # None when another program has the keyboard
        except Exception:  # noqa: BLE001  (Tk can raise KeyError for pop-down lists)
            return False
        return isinstance(w, (tk.Entry, tk.Text, tk.Spinbox, ttk.Entry, ttk.Spinbox, ttk.Combobox))

    def _menu_closed(self):
        """A menu was closed: take the cursor out of the chat box, so the hotkeys work again."""
        if self._open_popups:
            return  # another menu is open (e.g. slots menu -> editor)
        try:
            self.root.focus_set()
        except tk.TclError:
            pass

    def _poll(self):
        try:
            self.has_focus = self._typing_here()  # True = the cursor is in one of our text boxes
        except tk.TclError:
            self.has_focus = False
        eng = getattr(self, "engine", None)
        if eng is not None:
            eng.paused = bool(self.cfg.get("pause_when_focused", True)) and self.has_focus
        try:
            while True:
                fn, args = self.q.get_nowait()
                try:
                    fn(*args)
                except Exception:  # noqa: BLE001
                    traceback.print_exc()
        except queue.Empty:
            pass
        self.root.after(40, self._poll)

    # ---------- helpers ----------
    def update_title(self):
        self.title_label.config(text=self.cfg["title"])
        slots, i = self.cfg.get("slots") or [], self.cfg.get("active_slot", 0)
        name = slots[i]["name"] if isinstance(i, int) and 0 <= i < len(slots) else ""
        name = name if len(name) <= 14 else name[:13] + "\u2026"
        self.provider_label.config(text=f"{name} \u00b7 {self.cfg['provider']}" if name else self.cfg["provider"])
        self.root.title(self.cfg["title"])

    def apply_theme(self):
        bg = self.cfg.get("bg_color", DEFAULTS["bg_color"])
        if not HEX_RE.match(bg):
            bg = DEFAULTS["bg_color"]
        dark = luminance(bg) < 0.5
        fg = "#e8e8ea" if dark else "#16171a"
        input_bg = shade(bg, 0.16 if dark else -0.10)
        border = shade(bg, 0.35 if dark else -0.30)
        hdr = self.cfg.get("header_color", DEFAULTS["header_color"])
        btn = self.cfg.get("button_color", DEFAULTS["button_color"])
        if not HEX_RE.match(hdr):
            hdr = DEFAULTS["header_color"]
        if not HEX_RE.match(btn):
            btn = DEFAULTS["button_color"]
        hdr_fg = "#ffffff" if luminance(hdr) < 0.6 else "#16171a"
        btn_fg = "#ffffff" if luminance(btn) < 0.6 else "#16171a"
        self.header.configure(bg=hdr)
        self.title_label.configure(bg=hdr, fg=hdr_fg)
        self.provider_label.configure(bg=hdr, fg=hdr_fg)
        self.send_btn.configure(bg=btn, fg=btn_fg, activebackground=shade(btn, -0.15),
                                activeforeground=btn_fg)
        self.root.configure(bg=bg)
        self.bottom.configure(bg=bg)
        self.chat.configure(bg=bg, fg=fg)
        self.chat.tag_config("user", foreground="#9fb4ff" if dark else "#2a49c9")
        self.chat.tag_config("ai", foreground=fg)
        self.chat.tag_config("sys", foreground="#8a8a8a")
        try:
            size = min(24, max(7, int(self.cfg.get("font_size", DEFAULTS["font_size"]))))
        except (TypeError, ValueError):
            size = DEFAULTS["font_size"]
        self.chat.configure(font=("Sans", size))
        self.entry.configure(font=("Sans", size))
        self.send_btn.configure(font=("Sans", size))
        self.chat.tag_config("bold", font=("Sans", size, "bold"))
        self.chat.tag_config("italic", font=("Sans", size, "italic"))
        self.chat.tag_config("bolditalic", font=("Sans", size, "bold italic"))
        self.chat.tag_config("heading", font=("Sans", size + 1, "bold"))
        self.chat.tag_config("code", font=("Monospace", max(6, size - 1)), background=input_bg)
        self.chat.tag_config("codeblock", font=("Monospace", max(6, size - 1)), background=input_bg,
                             lmargin1=8, lmargin2=8)
        self.entry.configure(bg=input_bg, fg=fg, insertbackground=fg, highlightthickness=1,
                             highlightbackground=border, highlightcolor=btn)

    def persona_text(self):
        """The hidden instruction for the chosen persona ('' = none)."""
        name = self.cfg.get("persona", "Default")
        if name == "Custom":
            return str(self.cfg.get("custom_persona", "")).strip()
        return PERSONAS.get(name, "")

    def get_api_key(self, provider):
        key = self.cfg["providers"][provider].get("api_key", "").strip()
        env = PROVIDERS[provider]["env"]
        key = key or (os.environ.get(env, "") if env else "")
        return "".join(key.split())  # removes spaces/newlines from bad pastes

    # ---------- geometry ----------
    def apply_geometry(self):
        sw, sh = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
        w = min(max(S(200), S(int(self.cfg["width"]))), sw)   # never bigger than this screen
        h = min(max(S(150), S(int(self.cfg["height"]))), sh)
        ox, oy = S(int(self.cfg["offset_x"])), S(int(self.cfg["offset_y"]))
        corner = self.cfg["corner"]
        x = ox if "Left" in corner else sw - w - ox
        y = sh - h - oy if "Bottom" in corner else oy
        if self.cfg.get("use_exact_position"):
            x, y = int(self.cfg.get("pos_x", x)), int(self.cfg.get("pos_y", y))
        x = max(0, min(x, sw - w))                      # and never off-screen (other laptop, smaller screen)
        y = max(0, min(y, sh - h))
        self.root.geometry(f"{w}x{h}+{x}+{y}")

    # ---------- interface size (high-resolution screens) ----------
    def _init_scaling(self):
        """On 4K / high-DPI screens Tk does not make anything bigger by itself, so the window and the
        menus would look tiny. Work out a scale (or use the one chosen in Settings > Window)."""
        sw, sh = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
        try:
            dpi_factor = float(self.root.tk.call("tk", "scaling")) / (96 / 72)
        except (tk.TclError, ValueError, TypeError):
            dpi_factor = 1.0
        setting = (os.environ.get("AIWINDOW_SCALE") or str(self.cfg.get("ui_scale", "auto"))).strip().lower()
        scale = None
        if setting not in ("", "auto"):
            try:
                scale = float(setting[:-1]) / 100 if setting.endswith("%") else float(setting)
            except ValueError:
                scale = None
        if scale is None:  # automatic: follow the DPI, and grow on big screens that report a normal DPI
            res = min(sw / 1920, sh / 1080)
            scale = round(max(dpi_factor, res if res >= 1.2 else 1.0) * 4) / 4
        scale = min(3.0, max(0.75, scale))
        UI_SCALE[0] = scale
        if abs(scale - dpi_factor) > 0.12:  # make fonts follow the scale too
            try:
                self.root.tk.call("tk", "scaling", (96 / 72) * scale)
            except tk.TclError:
                pass
        self._write_info(sw, sh, dpi_factor, scale)

    def _write_info(self, sw, sh, dpi_factor, scale):
        """A small text file about this computer's screen, handy if something looks wrong somewhere."""
        try:
            lines = ["AI Window info (send this file if something looks wrong)", f"version: {VERSION}",
                     f"screen: {sw}x{sh}", f"tk: {self.root.tk.call('info', 'patchlevel')}",
                     f"tk dpi factor: {dpi_factor:.2f}", f"interface scale used: {scale}",
                     f"session: {os.environ.get('XDG_SESSION_TYPE', '?')}",
                     f"desktop: {os.environ.get('XDG_CURRENT_DESKTOP', '?')}",
                     f"packaged: {bool(getattr(sys, 'frozen', False))}", f"python: {sys.version.split()[0]}"]
            with open(os.path.join(_APP_DIR, "ai_window_info.txt"), "w", encoding="utf-8") as f:
                f.write("\n".join(lines) + "\n")
        except (OSError, tk.TclError):
            pass

    # ---------- menus (pop-up windows without a title bar) ----------
    def _menu_styles(self, win):
        """The purple look of the menus, scaled for this screen."""
        style = ttk.Style(win)
        try:
            style.theme_use("clam")  # the plain default theme ignores most colors
        except tk.TclError:
            pass
        arrow = S(14)
        style.configure("S.TLabel", background=MENU_BG, foreground=MENU_FG)
        style.configure("S.TFrame", background=MENU_BG)
        style.configure("S.TCheckbutton", background=MENU_BG, foreground=MENU_FG, indicatorsize=S(13))
        style.map("S.TCheckbutton", background=[("active", MENU_BG)], foreground=[("active", MENU_FG)])
        style.configure("TNotebook", background=MENU_BG, borderwidth=0)
        style.configure("TNotebook.Tab", background=MENU_TAB, foreground=MENU_FG, padding=(S(8), S(4)),
                        borderwidth=0)
        style.map("TNotebook.Tab", background=[("selected", MENU_BUTTON), ("active", MENU_BUTTON_ACTIVE)],
                  foreground=[("selected", MENU_FG), ("active", MENU_FG)])
        style.configure("TButton", background=MENU_BUTTON, foreground=MENU_FG, borderwidth=0,
                        padding=(S(10), S(4)))
        style.map("TButton", background=[("active", MENU_BUTTON_ACTIVE), ("pressed", MENU_BUTTON_ACTIVE)],
                  foreground=[("active", MENU_FG)])
        style.configure("Vertical.TScrollbar", background=MENU_BUTTON, troughcolor=MENU_TAB,
                        bordercolor=MENU_TAB, arrowcolor=MENU_FG, borderwidth=0, arrowsize=arrow)
        style.configure("TSpinbox", arrowsize=arrow)

    def _popup(self, width, height):
        """A hidden, centered menu window (sizes are for a normal screen, they grow with the interface
        scale). Build it, then call _show_popup(win)."""
        win = tk.Toplevel(self.root)
        win.withdraw()
        win.title("AI Window")
        win.configure(bg=MENU_BG)
        win.attributes("-topmost", True)
        win.resizable(False, False)
        sw, sh = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
        w = min(S(width), max(300, sw - 20))
        h = min(S(height), max(300, sh - 80))
        win.geometry(f"{w}x{h}+{max(0, (sw - w) // 2)}+{max(0, (sh - h) // 2)}")
        self._open_popups.add(win)

        def on_destroy(ev, win=win):
            if ev.widget is win:  # (the event also fires for every widget inside the menu)
                self._open_popups.discard(win)
                try:
                    self.root.after(80, self._menu_closed)
                except tk.TclError:
                    pass

        win.bind("<Destroy>", on_destroy)
        return win

    def _drag_bar(self, win, text):
        """A thin purple strip at the top of a menu: it shows the title and you drag it to move the menu."""
        bar = tk.Frame(win, bg=MENU_BUTTON)
        bar.pack(side="top", fill="x")
        lbl = tk.Label(bar, text=text, bg=MENU_BUTTON, fg=MENU_FG, font=("Sans", 10, "bold"))
        lbl.pack(side="left", padx=10, pady=S(4))
        state = {}

        def start(ev):
            state["d"] = (ev.x_root - win.winfo_x(), ev.y_root - win.winfo_y())

        def move(ev):
            d = state.get("d")
            if d:
                win.geometry(f"+{ev.x_root - d[0]}+{ev.y_root - d[1]}")

        for w in (bar, lbl):
            w.bind("<ButtonPress-1>", start)
            w.bind("<B1-Motion>", move)
        return bar

    def _show_popup(self, win):
        """Show a menu with NO title bar (no minimize / maximize / close) and give it the keyboard."""
        used_hint = self._set_motif_decorations(False, win)  # ask the window manager (X11 / XWayland)
        if not used_hint:
            win.overrideredirect(True)                         # can't ask: use an unmanaged window

        def grab_focus(_e=None):
            try:
                win.focus_force()
            except tk.TclError:
                pass

        win.deiconify()
        win.lift()
        win.attributes("-topmost", True)
        grab_focus()
        if not used_hint:
            win.bind("<ButtonPress-1>", grab_focus, add="+")  # unmanaged windows need to take focus themselves
        else:
            def verify():
                try:
                    if win.winfo_exists() and self._is_decorated(win):  # the hint was ignored
                        win.withdraw()
                        win.overrideredirect(True)
                        win.deiconify()
                        win.lift()
                        grab_focus()
                        win.bind("<ButtonPress-1>", grab_focus, add="+")
                except tk.TclError:
                    pass
            win.after(250, verify)

    # ---------- frameless window + dragging ----------
    def _wm_window_id(self, win=None):
        """Tk wraps its window in an outer 'wrapper' window, and that is the one the window manager
        reads its hints from. winfo_id() is the INNER window, so look up its parent."""
        inner = (win if win is not None else self.root).winfo_id()
        try:
            out = subprocess.run(["xwininfo", "-id", hex(inner), "-tree"], capture_output=True,
                                 text=True, timeout=3).stdout
            m = re.search(r"Parent window id:\s*(0x[0-9a-fA-F]+)", out)
            if m:
                return int(m.group(1), 16)
        except (subprocess.TimeoutExpired, OSError):
            pass
        return inner

    def _set_motif_decorations(self, decorated, win=None):
        """Ask the window manager to show/hide the title bar (works on X11 and XWayland)."""
        if not shutil.which("xprop"):
            return False
        try:
            (win if win is not None else self.root).update()  # make sure Tk has created the wrapper window
            value = "2, 0, 1, 0, 0" if decorated else "2, 0, 0, 0, 0"
            r = subprocess.run(["xprop", "-id", hex(self._wm_window_id(win)), "-f", "_MOTIF_WM_HINTS",
                                "32c", "-set", "_MOTIF_WM_HINTS", value],
                               capture_output=True, timeout=3)
            return r.returncode == 0
        except (tk.TclError, subprocess.TimeoutExpired, OSError):
            return False

    def _is_decorated(self, win=None):
        """True if the window manager's frame is taller than our window (= a title bar is drawn),
        False if not, None if it can't be measured."""
        try:
            w = win if win is not None else self.root
            frame = w.wm_frame()
            out = subprocess.run(["xwininfo", "-id", frame], capture_output=True, text=True,
                                 timeout=3).stdout
            height = int(re.search(r"Height:\s*(\d+)", out).group(1))
            return height - w.winfo_height() > 2
        except (tk.TclError, subprocess.TimeoutExpired, OSError, AttributeError, ValueError):
            return None

    def _verify_frameless(self):
        """Once the window is on screen: if it still has a title bar, switch to the fallback method."""
        if not self.cfg.get("frameless") or self._frameless_state is not None:
            return
        self.root.update()
        time.sleep(0.15)
        self.root.update()
        decorated = self._is_decorated()
        if decorated:  # the hint was ignored -> use an unmanaged window instead
            self._frameless_state = "fallback"
            self.root.withdraw()
            self.root.overrideredirect(True)
            self._reshow(verify=False)
        elif decorated is False:
            self._frameless_state = "ok"

    def _reshow(self, verify=True):
        self.root.deiconify()
        self.apply_geometry()
        self.apply_opacity()
        self.root.attributes("-topmost", True)
        self.root.lift()
        if verify:
            self._verify_frameless()

    def apply_frameless(self):
        """Remove (or bring back) the title bar with its close / minimize / maximize buttons."""
        want = bool(self.cfg.get("frameless", False))
        visible = self.root.state() == "normal"
        if visible:
            self.root.withdraw()
        used_hint = self._set_motif_decorations(not want)
        self._frameless_state = "fallback" if (want and not used_hint) else None
        # if the window manager can't be asked, fall back to an unmanaged (override-redirect) window
        self.root.overrideredirect(bool(want and not used_hint))
        if visible:
            self._reshow()

    def _drag_start(self, ev):
        self._drag = (ev.x_root - self.root.winfo_x(), ev.y_root - self.root.winfo_y(), False)

    def _drag_move(self, ev):
        if not getattr(self, "_drag", None):
            return
        dx, dy, _ = self._drag
        x, y = ev.x_root - dx, ev.y_root - dy
        if abs(x - self.root.winfo_x()) + abs(y - self.root.winfo_y()) > 0:
            self._drag = (dx, dy, True)
            self.root.geometry(f"+{x}+{y}")

    def _drag_end(self, _ev):
        drag, self._drag = getattr(self, "_drag", None), None
        if drag and drag[2]:  # it was really moved: remember the new position
            self.cfg["pos_x"], self.cfg["pos_y"] = self.root.winfo_x(), self.root.winfo_y()
            self.cfg["use_exact_position"] = True
            save_config(self.cfg)

    def apply_opacity(self):
        """Make the whole window see-through (needs a compositing desktop, which GNOME/KDE have)."""
        try:
            value = min(1.0, max(0.1, float(self.cfg.get("opacity", 1.0))))
            self.root.attributes("-alpha", value)
        except (tk.TclError, ValueError, TypeError):
            pass

    # ---------- show / hide ----------
    def show(self):
        self.show_no_focus()
        try:
            self.root.focus_force()  # (the cursor is NOT put in the chat box: click it to type)
        except tk.TclError:
            pass

    def show_no_focus(self):
        self.root.deiconify()
        self.apply_opacity()
        self.root.attributes("-topmost", True)
        self.root.lift()
        self._verify_frameless()

    def toggle_window(self):
        if self.root.state() == "normal":
            self.hide()
        else:
            self.show_no_focus()

    def hide(self):
        self.root.withdraw()
        if self.settings_win and self.settings_win.winfo_exists():
            self.settings_win.destroy()
            self.settings_win = None

    def quit_app(self):
        self.engine.shutdown()
        self.root.destroy()

    # ---------- chat ----------
    def append(self, tag, text):
        self.chat.config(state="normal")
        self.chat.insert("end", text, tag)
        self.chat.see("end")
        self.chat.config(state="disabled")

    # ---------- formatted AI answers ----------
    def _insert_inline(self, text, base):
        """Insert one line, turning **bold**, *italic*, `code` into styled text."""
        text = LINK_RE.sub(r"\1 (\2)", text)
        pos = 0
        for m in INLINE_RE.finditer(text):
            if m.start() > pos:
                self.chat.insert("end", text[pos:m.start()], base)
            tok = m.group(0)
            if tok.startswith("***"):
                self.chat.insert("end", tok[3:-3], base + ("bolditalic",))
            elif tok.startswith("**"):
                self.chat.insert("end", tok[2:-2], base + ("bold",))
            elif tok.startswith("`"):
                self.chat.insert("end", tok[1:-1], base + ("code",))
            else:
                self.chat.insert("end", tok[1:-1], base + ("italic",))
            pos = m.end()
        if pos < len(text):
            self.chat.insert("end", text[pos:], base)

    def append_ai(self, provider, reply):
        self.chat.config(state="normal")
        self.chat.insert("end", f"{provider}: ", ("ai", "bold"))
        in_code = False
        for line in reply.split("\n"):
            if line.strip().startswith("```"):
                in_code = not in_code
                continue
            if in_code:
                self.chat.insert("end", line + "\n", ("codeblock",))
                continue
            head = re.match(r"^#{1,6}\s+(.*)$", line)
            if head:
                self._insert_inline(head.group(1), ("ai", "heading"))
            elif re.match(r"^\s*([-*_])(\s*\1){2,}\s*$", line):  # --- / *** separator
                self.chat.insert("end", "\u2500" * 24, ("ai",))
            else:
                bullet = re.match(r"^(\s*)[-*+]\s+(.*)$", line)
                if bullet:
                    line = bullet.group(1) + "\u2022 " + bullet.group(2)
                self._insert_inline(line, ("ai",))
            self.chat.insert("end", "\n", ("ai",))
        self.chat.insert("end", "\n", ("ai",))
        self.chat.see("end")
        self.chat.config(state="disabled")

    def send(self, _event=None):
        text = self.entry.get().strip()
        if text:
            self.entry.delete(0, "end")
            self.submit(text)

    def submit(self, text, image=None):
        if image:
            self.append("user", "You: [screenshot sent]\n")
            for old in self.history:  # keep only the newest screenshot (saves tokens/memory)
                if old.pop("image", None):
                    old["content"] += " [earlier screenshot omitted]"
        else:
            self.append("user", f"You: {text}\n")
        msg = {"role": "user", "content": text}
        if image:
            msg["image"] = image
        self.history.append(msg)
        threading.Thread(target=self.get_reply, args=(msg,), daemon=True).start()

    def _drop(self, msg):
        try:
            self.history.remove(msg)
        except ValueError:
            pass

    def get_reply(self, msg):
        provider = self.cfg["provider"]
        key = self.get_api_key(provider)
        model = self.cfg["providers"][provider]["model"]

        if not key and provider not in NO_KEY_NEEDED:
            self._drop(msg)
            self.ui(self.append, "sys", f"No API key for {provider}. Press {label('settings')} "
                                        f"and enter one (or set {PROVIDERS[provider]['env']}).\n\n")
            return
        if provider not in NO_KEY_NEEDED and len(key) < 20:
            self._drop(msg)
            self.ui(self.append, "sys", f"The {provider} API key looks wrong (too short). Press "
                                        f"{label('settings')}, clear the key field and paste the real key.\n\n")
            return
        try:
            reply = None
            for attempt in range(3):
                try:
                    reply = ask_ai(provider, key, model, list(self.history), self.persona_text())
                    break
                except (RuntimeError, requests.exceptions.RequestException) as err:
                    network = (isinstance(err, (requests.exceptions.Timeout,
                                                requests.exceptions.ConnectionError))
                               and provider not in NO_KEY_NEEDED)
                    temporary = network or any(f"HTTP {c}" in str(err)
                                               for c in (429, 500, 502, 503, 504))
                    if not temporary or attempt == 2:
                        raise
                    self.ui(self.append, "sys", f"{provider} is busy, retrying "
                                                f"({attempt + 2}/3)...\n")
                    time.sleep(3 * (attempt + 1))
            if not reply or not reply.strip():
                raise RuntimeError("The AI returned an empty answer. Try rephrasing, or check the model name.")
        except Exception as err:  # noqa: BLE001
            self._drop(msg)
            self.ui(self.append, "sys", f"Error ({provider}): {err}\n\n")
            return

        self.history.append({"role": "assistant", "content": reply})
        self.last_answer = reply
        self.ui(self.append_ai, provider, reply)

    # ---------- auto prompt on start ----------
    def send_auto_prompt(self):
        """If enabled in the menu, send the saved prompt to the AI as soon as the program starts."""
        if not self.cfg.get("auto_prompt_enabled"):
            return
        text = str(self.cfg.get("auto_prompt", "")).strip()
        if text:
            self.submit(text)

    # ---------- Shift+C : highlighted text -> AI ----------
    def ask_selection(self):
        text = read_selection()
        self.ui(self.show_no_focus)
        if not text:
            self.ui(self.append, "sys", "Nothing highlighted. Select some text first, then press "
                                        f"{label('ask')}.\n\n")
            return
        self.ui(self.submit, text)

    # ---------- screenshot keys : screenshot -> AI ----------
    def ask_screenshot(self, slot=1):
        key_name = "screenshot" if slot == 1 else "screenshot2"
        mode = self.cfg.get("screenshot_mode" if slot == 1 else "screenshot2_mode",
                            "area" if slot == 1 else "full")
        keep = bool(self.cfg.get("screenshot_keep_focus", DEFAULTS["screenshot_keep_focus"]))
        state, ready = {}, threading.Event()

        def reveal():
            # bring the window back after the screenshot. With 'keep focus' on, the window is never
            # re-opened (that is what steals the focus): it was only made see-through, so it just
            # becomes solid again, and a window that was closed stays closed.
            if keep and not state.get("withdrawn"):
                if state.get("visible"):
                    self.apply_opacity()
            else:
                self.show_no_focus()

        if mode not in ("area", "full"):
            self.ui(reveal)
            self.ui(self.append, "sys", f"{label(key_name)} is switched off. "
                                        f"Turn it on in {label('settings')} > Screenshot.\n\n")
            return

        def prep():
            # hide our window so it is not in the screenshot / not in the way of the selection
            state["visible"] = self.root.state() == "normal"
            if state["visible"]:
                if keep:
                    try:
                        self.root.attributes("-alpha", 0.0)  # invisible, but still "open": no focus change
                    except tk.TclError:
                        self.root.withdraw()
                        state["withdrawn"] = True
                else:
                    self.root.withdraw()
            ready.set()

        self.ui(prep)
        ready.wait(2)
        if state.get("visible"):
            time.sleep(0.35)
        self.engine.wait_modifiers_released()

        try:
            png = capture_screen(mode, self.cfg.get("screenshot_tool", "auto"))
        except RuntimeError as err:
            self.ui(reveal)
            self.ui(self.append, "sys", f"Screenshot error: {err}\n\n")
            return
        self.ui(reveal)
        if png is None:
            detail = LAST_CAPTURE_INFO[0]
            print(f"[screenshot] cancelled: {detail}")
            self.ui(self.append, "sys", "Screenshot cancelled or no image returned"
                                        + (f" ({detail})" if detail else "")
                                        + (". After dragging the area, confirm it (Enter, or click the "
                                           "check / shutter button)." if mode == "area" else ".")
                                        + "\n\n")
            return
        png = fit_png(png)
        if png is None:
            self.ui(self.append, "sys", "That screenshot is too big to send. "
                                        + ("Select a smaller area." if mode == "area" else
                                           "Install Pillow (sudo apt install python3-pil) so it can be shrunk, "
                                           "or use select-area mode.") + "\n\n")
            return
        prompt = (self.cfg.get("screenshot_prompt") or DEFAULTS["screenshot_prompt"]).strip()
        self.ui(self.submit, prompt, base64.b64encode(png).decode("ascii"))

    # ---------- Shift+V : answer -> active app ----------
    def set_clipboard(self, text):
        done = threading.Event()

        def tk_set():
            try:
                self.root.clipboard_clear()
                self.root.clipboard_append(text)
                self.root.update()
            except tk.TclError:
                pass
            done.set()

        self.ui(tk_set)
        done.wait(2)
        _push(["xclip", "-selection", "clipboard", "-i"], text)
        if ON_WAYLAND and not IS_GNOME:
            _push(["wl-copy"], text)

    def paste_answer(self):
        if not self.last_answer:
            self.ui(self.show_no_focus)
            self.ui(self.append, "sys", "No answer to paste yet.\n\n")
            return

        state, ready = {}, threading.Event()

        def prep():
            # if our window has focus, hide it so focus goes back to the previous app
            state["focused"] = self.root.focus_displayof() is not None
            if state["focused"]:
                self.root.withdraw()
            ready.set()

        self.ui(prep)
        ready.wait(2)
        if state.get("focused"):
            time.sleep(0.35)

        self.set_clipboard(self.last_answer)
        time.sleep(0.1)
        self.engine.send_paste()
        time.sleep(0.2)

        if state.get("focused"):
            self.ui(self.show_no_focus)

    # ---------- Shift+B : type the answer letter by letter ----------
    def _type_fallback(self, ch):
        """For characters the layout table doesn't know: paste just that one character."""
        self.set_clipboard(ch)
        time.sleep(0.08)
        self.engine.send_paste()

    def type_answer(self):
        if not self.last_answer:
            self.ui(self.show_no_focus)
            self.ui(self.append, "sys", "No answer to type yet.\n\n")
            return

        state, ready = {}, threading.Event()

        def prep():
            state["focused"] = self.root.focus_displayof() is not None
            if state["focused"]:
                self.root.withdraw()
            ready.set()

        self.ui(prep)
        ready.wait(2)
        if state.get("focused"):
            time.sleep(0.35)

        choice = self.cfg.get("layout", "auto")
        layout = detect_layout() if choice == "auto" else choice
        used_fallback = self.engine.type_text(self.last_answer, layout,
                                              self.cfg.get("newline_mode", "Shift+Enter"),
                                              self._type_fallback,
                                              delay=float(self.cfg.get("type_delay", TYPE_DELAY)))
        if used_fallback:
            self.set_clipboard(self.last_answer)  # put the full answer back on the clipboard
        if state.get("focused"):
            self.ui(self.show_no_focus)

    # ---------- fun: spinning horse ----------
    def apply_fun(self):
        """Start the fun things that are switched on in the menu (called at start-up)."""
        if self.cfg.get("fun_horse"):
            self.start_horse()
        if self.cfg.get("fun_pirate"):
            self.start_pirate()
        self.schedule_jumpscare()

    def _fun_bg(self):
        bg = self.cfg.get("bg_color", DEFAULTS["bg_color"])
        return bg if HEX_RE.match(str(bg)) else DEFAULTS["bg_color"]

    def _load_gif(self, b64, size, bg):
        """Read an embedded GIF: returns (frames, delays in ms, (width, height)). The longer side is `size`
        pixels. A window on Linux can't be see-through per pixel, so the see-through parts of the picture
        are painted with the color `bg` and the picture sits on a box of that color."""
        raw = base64.b64decode("".join(b64.split()))
        try:
            import io
            from PIL import Image, ImageSequence, ImageTk
            im = Image.open(io.BytesIO(raw))
            t = size / max(im.width, im.height)
            w, h = max(1, round(im.width * t)), max(1, round(im.height * t))
            frames, delays = [], []
            for fr in ImageSequence.Iterator(im):
                rgba = fr.convert("RGBA").resize((w, h), Image.LANCZOS)
                back = Image.new("RGBA", (w, h), bg)
                back.alpha_composite(rgba)
                frames.append(ImageTk.PhotoImage(back.convert("RGB")))
                delays.append(max(20, int(fr.info.get("duration") or 60)))
            if frames:
                return frames, delays, (w, h)
        except Exception:  # noqa: BLE001  (Pillow or its Tk part is not installed)
            pass
        # without Pillow Tk can still show the first picture of the GIF (it just doesn't move)
        img = tk.PhotoImage(data="".join(b64.split()), format="gif -index 0")
        f = max(1, round(max(img.width(), img.height()) / size))
        if f > 1:
            img = img.subsample(f)
        return [img], [1000], (img.width(), img.height())

    def _sprite_window(self, frames, bg, w, h, x, y):
        """A small always-on-top window without a frame that shows picture 0 of a GIF."""
        win = tk.Toplevel(self.root)
        win.overrideredirect(True)  # no frame, and it does not steal the keyboard focus
        win.attributes("-topmost", True)
        win.configure(bg=bg)
        canvas = tk.Canvas(win, width=w, height=h, bg=bg, highlightthickness=0, bd=0)
        canvas.pack()
        item = canvas.create_image(0, 0, image=frames[0], anchor="nw")
        win.geometry(f"{w}x{h}+{int(x)}+{int(y)}")
        return win, canvas, item

    def start_horse(self):
        self.stop_horse()
        try:
            size = S(min(300, max(80, int(self.cfg.get("horse_size", DEFAULTS["horse_size"])))))
        except (TypeError, ValueError):
            size = S(DEFAULTS["horse_size"])
        bg = self._fun_bg()
        try:
            frames, delays, (w, h) = self._load_gif(HORSE_GIF_B64, size, bg)
        except Exception as err:  # noqa: BLE001
            self.append("sys", f"Horse picture problem: {err}\n\n")
            return
        sw, sh = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
        x, y = float(max(0, sw - w - 40)), float(max(0, sh - h - 80))
        win, canvas, item = self._sprite_window(frames, bg, w, h, x, y)
        horse = {"win": win, "canvas": canvas, "item": item, "frames": frames, "delays": delays, "i": 0,
                 "dir": 1, "w": w, "h": h, "x": x, "y": y,
                 "vx": 3.0 * UI_SCALE[0], "vy": 2.0 * UI_SCALE[0], "job": None}
        canvas.bind("<Button-1>", lambda _ev: horse.__setitem__("dir", -horse["dir"]))  # click = spin the other way
        self.horse = horse
        self._horse_tick()

    def _horse_tick(self):
        h = self.horse
        if not h:
            return
        try:
            h["i"] = (h["i"] + h["dir"]) % len(h["frames"])
            h["canvas"].itemconfigure(h["item"], image=h["frames"][h["i"]])
            if self.cfg.get("horse_bounce", True):
                sw, sh = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
                h["x"] += h["vx"]
                h["y"] += h["vy"]
                if h["x"] <= 0 or h["x"] >= sw - h["w"]:
                    h["vx"] = -h["vx"]
                    h["x"] = min(max(h["x"], 0), sw - h["w"])
                if h["y"] <= 0 or h["y"] >= sh - h["h"]:
                    h["vy"] = -h["vy"]
                    h["y"] = min(max(h["y"], 0), sh - h["h"])
                h["win"].geometry(f"+{int(h['x'])}+{int(h['y'])}")
            h["job"] = self.root.after(h["delays"][h["i"]], self._horse_tick)
        except tk.TclError:
            self.stop_horse()

    def stop_horse(self):
        h, self.horse = self.horse, None
        if not h:
            return
        try:
            if h.get("job"):
                self.root.after_cancel(h["job"])
            h["win"].destroy()
        except tk.TclError:
            pass

    # ---------- fun: the pirate at the bottom of the screen ----------
    def start_pirate(self):
        self.stop_pirate()
        try:
            size = S(min(400, max(80, int(self.cfg.get("pirate_size", DEFAULTS["pirate_size"])))))
            lift = S(min(600, max(0, int(self.cfg.get("pirate_lift", 0)))))
        except (TypeError, ValueError):
            size, lift = S(DEFAULTS["pirate_size"]), 0
        bg = self._fun_bg()
        try:
            frames, delays, (w, h) = self._load_gif(PIRATE_GIF_B64, size, bg)
        except Exception as err:  # noqa: BLE001
            self.append("sys", f"Pirate picture problem: {err}\n\n")
            return
        sw, sh = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
        side = self.cfg.get("pirate_side", "Right")
        x = 0 if side == "Left" else (sw - w) // 2 if side == "Middle" else sw - w
        y = max(0, sh - h - lift)
        win, canvas, item = self._sprite_window(frames, bg, w, h, max(0, x), y)
        self.pirate = {"win": win, "canvas": canvas, "item": item, "frames": frames, "delays": delays,
                       "i": 0, "job": None}
        self._pirate_tick()

    def _pirate_tick(self):
        p = self.pirate
        if not p:
            return
        try:
            p["i"] = (p["i"] + 1) % len(p["frames"])
            p["canvas"].itemconfigure(p["item"], image=p["frames"][p["i"]])
            p["job"] = self.root.after(p["delays"][p["i"]], self._pirate_tick)
        except tk.TclError:
            self.stop_pirate()

    def stop_pirate(self):
        p, self.pirate = self.pirate, None
        if not p:
            return
        try:
            if p.get("job"):
                self.root.after_cancel(p["job"])
            p["win"].destroy()
        except tk.TclError:
            pass

    # ---------- fun: random jump scare ----------
    def schedule_jumpscare(self):
        """(Re)start the timer for the next random jump scare, if it is switched on."""
        self.cancel_jumpscare()
        if not self.cfg.get("jumpscare_enabled"):
            return
        try:
            lo = max(1, int(self.cfg.get("jumpscare_min", DEFAULTS["jumpscare_min"])))
            hi = max(lo, int(self.cfg.get("jumpscare_max", DEFAULTS["jumpscare_max"])))
        except (TypeError, ValueError):
            lo, hi = DEFAULTS["jumpscare_min"], DEFAULTS["jumpscare_max"]
        self.scare_job = self.root.after(int(random.uniform(lo, hi) * 60 * 1000), self._scare_fire)

    def cancel_jumpscare(self):
        if self.scare_job is not None:
            try:
                self.root.after_cancel(self.scare_job)
            except tk.TclError:
                pass
            self.scare_job = None

    def _scare_fire(self):
        self.scare_job = None
        self.show_jumpscare()
        self.schedule_jumpscare()

    def _scare_photo(self):
        """The dog picture, sized for this screen (smooth with Pillow, otherwise in simple steps)."""
        sw, sh = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
        if self._scare_cache and self._scare_cache[0] == (sw, sh):
            return self._scare_cache[1]
        data = "".join(DOG_PNG_B64.split())
        photo = None
        try:
            import io
            from PIL import Image, ImageTk
            img = Image.open(io.BytesIO(base64.b64decode(data))).convert("RGB")
            t = min(sw * 0.95 / img.width, sh * 0.95 / img.height)
            img = img.resize((max(1, int(img.width * t)), max(1, int(img.height * t))), Image.LANCZOS)
            photo = ImageTk.PhotoImage(img)
        except Exception:  # noqa: BLE001  (Pillow / its Tk part not installed)
            photo = None
        if photo is None:
            base = tk.PhotoImage(data=data)
            t = min(sw * 0.95 / base.width(), sh * 0.95 / base.height())
            p, q = 1, 1
            for p, q in ((2, 1), (3, 2), (1, 1)):
                if p / q <= t:
                    break
            photo = base if (p, q) == (1, 1) else base.zoom(p, p).subsample(q, q)
        self._scare_cache = ((sw, sh), photo)
        return photo

    def show_jumpscare(self):
        if self.scare_win is not None:
            return
        try:
            photo = self._scare_photo()
        except Exception as err:  # noqa: BLE001
            self.append("sys", f"Jump scare picture problem: {err}\n\n")
            return
        sw, sh = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
        win = tk.Toplevel(self.root)
        win.overrideredirect(True)  # no frame, and it does not steal the keyboard focus
        win.geometry(f"{sw}x{sh}+0+0")
        win.configure(bg="black")
        win.attributes("-topmost", True)
        canvas = tk.Canvas(win, bg="black", highlightthickness=0, bd=0)
        canvas.pack(fill="both", expand=True)
        item = canvas.create_image(sw // 2, sh // 2, image=photo)
        self.scare_win = win

        def close(_ev=None):
            if self.scare_win is win:
                self.scare_win = None
                try:
                    win.destroy()
                except tk.TclError:
                    pass

        def shake():
            if self.scare_win is not win:
                return
            try:
                canvas.coords(item, sw // 2 + random.randint(-14, 14), sh // 2 + random.randint(-14, 14))
                win.after(35, shake)
            except tk.TclError:
                pass

        canvas.bind("<Button-1>", close)  # click to close, otherwise it goes away by itself
        win.after(2500, close)
        win.lift()
        shake()

    # ---------- settings menu ----------
    # ---------- updates ----------
    def _update_url(self):
        return os.environ.get("AIWINDOW_UPDATE_URL") or UPDATE_MANIFEST_URL

    def check_update_async(self):
        """Look for a newer version in the background (the program never waits for the internet)."""
        url = self._update_url()
        if not url or self.update_state in ("checking", "installing", "installed"):
            return
        self.update_state, self.update_text = "checking", "Checking for updates..."
        self._refresh_update_row()

        def work():
            self.ui(self._update_checked, fetch_update_info(url))

        threading.Thread(target=work, daemon=True).start()

    def _update_checked(self, info):
        self.update_checked_at = time.time()
        self.update_state = info["state"]
        self.update_info = info if info["state"] == "available" else None
        if info["state"] != "error":
            self.update_versions = info.get("versions", [])
        self.update_text = info.get("message", "")
        if info["state"] == "available" and self._update_announced != info["version"]:
            self._update_announced = info["version"]
            self.append("sys", f"Update available: {info['version']}. Press {label('settings')} and "
                               f"click the Update button.\n\n")
        self._refresh_update_row()

    def install_update_async(self, info=None):
        """Download and install a version: the newest one (no argument) or the one picked in the picker."""
        info = info or self.update_info
        if not info or self.update_state not in ("available", "uptodate", "error"):
            return
        self.update_state, self.update_text = "installing", f"Downloading {info['version']}..."
        self._refresh_update_row()

        def work():
            try:
                install_update(download_update(info), info["version"])
            except RuntimeError as err:
                self.ui(self._update_failed, str(err))
            except OSError as err:
                self.ui(self._update_failed, f"Could not save the update ({err.__class__.__name__}).")
            else:
                self.ui(self._update_installed, info["version"])

        threading.Thread(target=work, daemon=True).start()

    def install_picked_version(self):
        info = next((v for v in self.update_versions if v["version"] == self.update_pick), None)
        if info:
            self.install_update_async(info)

    def _update_failed(self, message):
        self.update_state = "available" if self.update_info else "uptodate"
        self.update_text = message
        self._refresh_update_row()

    def _update_installed(self, version):
        verb = "Updated" if version_tuple(version) > version_tuple(VERSION) else "Switched"
        self.update_state, self.update_text = "installed", f"{verb} to {version}. Restarting..."
        self._refresh_update_row()
        self.root.after(900, self._restart)

    def _restart(self):
        """Start the program again (now the new version) and close this one."""
        try:
            if getattr(sys, "frozen", False):
                env = dict(os.environ)
                env["PYINSTALLER_RESET_ENVIRONMENT"] = "1"  # the new copy unpacks itself fresh
                env.pop("_MEIPASS2", None)
                env.pop("AIW_RUNNING_UPDATE", None)
                env.pop("AIW_BUILTIN_VERSION", None)
                subprocess.Popen([sys.executable] + sys.argv[1:], env=env, start_new_session=True, close_fds=True)
            else:
                subprocess.Popen([sys.executable, os.path.abspath(__file__)] + sys.argv[1:],
                                 start_new_session=True, close_fds=True)
        except OSError:
            self.update_text = "Updated! Please close the program and open it again."
            self._refresh_update_row()
            return
        self.root.after(400, self.quit_app)

    def _refresh_update_row(self):
        """(Re)draw the update line at the top of the slots menu, if that menu is open."""
        row = self._update_row
        if not row:
            return
        win, frame = row
        try:
            if not win.winfo_exists():
                self._update_row = None
                return
            for child in frame.winfo_children():
                child.destroy()
            state, text = self.update_state, self.update_text

            def small_button(label_text, command):
                tk.Button(frame, text=label_text, bg=MENU_BUTTON, fg=MENU_FG, activebackground=MENU_BUTTON_ACTIVE,
                          activeforeground=MENU_FG, relief="flat", padx=S(10), command=command).pack(side="right")

            if state == "available":
                info = self.update_info or {}
                tk.Button(frame, text=f"\u2B06  Update available: {info.get('version', '')}  -  click to update",
                          bg="#1f9d55", fg="#ffffff", activebackground="#27b866", activeforeground="#ffffff",
                          relief="flat", pady=S(5), command=self.install_update_async).pack(fill="x")
                note = info.get("notes") or ""
                if text or note:
                    tk.Label(frame, text=text or note, bg=MENU_BG, fg=MENU_ERR if text else MENU_HINT,
                             font=("Sans", 8), anchor="w", justify="left", wraplength=S(430)).pack(fill="x", pady=(S(3), 0))
            else:
                shown = text or f"Version {VERSION}"
                tk.Label(frame, text=shown, bg=MENU_BG, fg=MENU_ERR if state == "error" else MENU_HINT,
                         font=("Sans", 8), anchor="w", justify="left", wraplength=S(330)).pack(side="left")
                if state in ("idle", "uptodate"):
                    small_button("Check for updates", self.check_update_async)
                elif state == "error":
                    small_button("Try again", self.check_update_async)

            # the version picker: install ANY version the update address lists (newer or older)
            if self.update_versions and state in ("available", "uptodate", "error"):
                names = [v["version"] for v in self.update_versions]
                if self.update_pick not in names:
                    self.update_pick = VERSION if VERSION in names else names[0]
                pick = tk.Frame(frame, bg=MENU_BG)
                pick.pack(fill="x", pady=(S(6), 0))
                tk.Label(pick, text="Choose version:", bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8)).pack(side="left")
                var = tk.StringVar(value=self.update_pick)

                def labelled(name):
                    return f"{name}  (installed)" if name == VERSION else name

                def on_pick(name):
                    self.update_pick = name
                    self.root.after(10, self._refresh_update_row)  # redraw after the drop-down has closed

                menu = tk.OptionMenu(pick, var, *names, command=on_pick)
                menu.config(bg=MENU_BUTTON, fg=MENU_FG, activebackground=MENU_BUTTON_ACTIVE, activeforeground=MENU_FG,
                            relief="flat", highlightthickness=0, width=14)
                menu["menu"].config(bg=MENU_BUTTON, fg=MENU_FG, activebackground=MENU_BUTTON_ACTIVE,
                                    activeforeground=MENU_FG)
                for i, name in enumerate(names):
                    menu["menu"].entryconfigure(i, label=labelled(name))
                menu.pack(side="left", padx=S(6))
                chosen = next(v for v in self.update_versions if v["version"] == self.update_pick)
                same = chosen["version"] == VERSION
                older = version_tuple(chosen["version"]) < version_tuple(VERSION)
                tk.Button(pick, text="Already installed" if same else ("Install older version" if older else "Install"),
                          bg=MENU_BUTTON, fg=MENU_FG, activebackground=MENU_BUTTON_ACTIVE, activeforeground=MENU_FG,
                          relief="flat", padx=S(10), state="disabled" if same else "normal",
                          command=self.install_picked_version).pack(side="right")
                if chosen.get("notes"):
                    tk.Label(frame, text=chosen["notes"], bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w",
                             justify="left", wraplength=S(430)).pack(fill="x", pady=(S(3), 0))
        except tk.TclError:
            self._update_row = None

    # ---------- save slots ----------
    def toggle_settings(self):
        """Shift+M: open the save-slots menu, or close whichever menu is open."""
        closers = [c for c in (self._edit_cancel, self._slots_close, self._settings_save) if c]
        if closers:
            for close in closers:
                close()
            return
        self.show()
        self.open_slots()

    def use_slot(self, i):
        """Switch to save slot i: its AI settings and colors become the live ones."""
        if not 0 <= i < len(self.cfg["slots"]):
            return
        sync_active_slot(self.cfg)  # keep whatever you changed in the slot you are leaving
        was_frameless = bool(self.cfg.get("frameless", False))
        apply_slot(self.cfg, i)
        self.apply_slot_settings(was_frameless)
        save_config(self.cfg)

    def apply_slot_settings(self, was_frameless):
        """Put every setting of the slot that was just switched to into use, right now."""
        self.apply_keybinds()                    # keys and modifier
        self.apply_theme()                       # colors and text size
        self.apply_opacity()
        self.apply_geometry()                    # size, corner, offsets, exact position
        if bool(self.cfg.get("frameless", False)) != was_frameless:
            self.apply_frameless()               # title bar on / off
        self.update_title()                      # window name and slot name
        self.stop_horse()                        # fun tab: the right things on, the others off
        self.stop_pirate()
        self.apply_fun()                         # (this also restarts the jump scare timer)

    def _slot_photo(self, slot, size):
        """The slot's photo as a Tk picture about `size` pixels wide (None = no photo)."""
        data = slot.get("photo") or ""
        if not data:
            return None
        try:
            img = tk.PhotoImage(data=data)
            f = max(1, img.width() // max(1, size))
            return img.subsample(f) if f > 1 else img
        except tk.TclError:
            return None

    def open_slots(self):
        """The save-slots menu: click a slot to use it, Edit to rename it / change its photo and colors."""
        if self.slots_win is not None and self.slots_win.winfo_exists():
            self.slots_win.lift()
            return
        win = self._popup(470, 580)
        self.slots_win = win
        self._menu_styles(win)
        self._drag_bar(win, "Save slots")
        photos = []  # keeps the pictures alive while the menu is open

        if self._update_url():  # the update line (only when an update address is set)
            upd = tk.Frame(win, bg=MENU_BG)
            upd.pack(side="top", fill="x", padx=S(10), pady=(S(8), 0))
            self._update_row = (win, upd)
            if self.update_state == "idle" or (self.update_state in ("uptodate", "error")
                                               and time.time() - self.update_checked_at > 3600):
                self.update_state = "idle"
                self.check_update_async()
            self._refresh_update_row()

        tk.Label(win, text=f"Made by Invis  \u00b7  {VERSION}", bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8),
                 anchor="e").pack(side="bottom", fill="x", padx=10, pady=(0, S(4)))
        btns = tk.Frame(win, bg=MENU_BG)
        btns.pack(side="bottom", pady=S(10))
        tk.Label(win, text="Click a slot to use it. Each slot remembers every setting. "
                           "Edit: name, description, photo and colors.",
                 bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), wraplength=S(430),
                 justify="center").pack(side="bottom")
        body = tk.Frame(win, bg=MENU_BG)
        body.pack(fill="both", expand=True, padx=S(10), pady=(S(8), 0))
        canvas = tk.Canvas(body, bg=MENU_BG, highlightthickness=0, bd=0)
        bar = ttk.Scrollbar(body, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=bar.set)
        inner = tk.Frame(canvas, bg=MENU_BG)
        item = canvas.create_window((0, 0), window=inner, anchor="nw")

        def refresh_scroll(_e=None):
            canvas.configure(scrollregion=canvas.bbox("all"))
            canvas.itemconfigure(item, width=canvas.winfo_width())
            need = inner.winfo_reqheight() > canvas.winfo_height()
            if need and not bar.winfo_ismapped():
                bar.pack(side="right", fill="y", before=canvas)
            elif not need and bar.winfo_ismapped():
                bar.pack_forget()
                canvas.yview_moveto(0)

        inner.bind("<Configure>", refresh_scroll)
        canvas.bind("<Configure>", refresh_scroll)
        canvas.pack(side="left", fill="both", expand=True)

        def on_wheel(ev):
            if canvas.yview() != (0.0, 1.0):
                canvas.yview_scroll(-1 if (getattr(ev, "num", 0) == 4 or getattr(ev, "delta", 0) > 0) else 1, "units")

        for seq in ("<Button-4>", "<Button-5>", "<MouseWheel>"):
            win.bind(seq, on_wheel)

        def close(_e=None):
            self._slots_close = None
            self._update_row = None
            self.slots_win = None
            try:
                win.destroy()
            except tk.TclError:
                pass

        def use(i):
            self.use_slot(i)
            close()

        def edit(i):
            self.use_slot(i)  # the editor works on the slot in use
            close()
            self.open_slot_editor()

        def add():
            if len(self.cfg["slots"]) >= MAX_SLOTS:
                return
            sync_active_slot(self.cfg)
            self.cfg["slots"].append(make_slot(self.cfg, f"Slot {len(self.cfg['slots']) + 1}"))
            save_config(self.cfg)
            render()

        def flat_button(parent, text, command, color=MENU_BUTTON, active=MENU_BUTTON_ACTIVE):
            return tk.Button(parent, text=text, bg=color, fg=MENU_FG, activebackground=active,
                             activeforeground=MENU_FG, relief="flat", padx=S(12), command=command)

        add_btn = flat_button(btns, "+ New slot (copy of this one)", add)
        add_btn.pack(side="left", padx=4)
        flat_button(btns, "Settings", lambda: (close(), self.open_settings())).pack(side="left", padx=4)
        flat_button(btns, "Close", close).pack(side="left", padx=4)

        def render():
            for child in inner.winfo_children():
                child.destroy()
            del photos[:]
            active_i = self.cfg.get("active_slot", 0)
            for i, slot in enumerate(self.cfg["slots"]):
                active = (i == active_i)
                bg, hdr, btn = slot["bg_color"], slot["header_color"], slot["button_color"]
                dark = luminance(bg) < 0.5
                fg = "#e8e8ea" if dark else "#16171a"
                sub = "#a9a9b4" if dark else "#555560"
                hdr_fg = "#ffffff" if luminance(hdr) < 0.6 else "#16171a"
                btn_fg = "#ffffff" if luminance(btn) < 0.6 else "#16171a"
                card = tk.Frame(inner, bg=bg, highlightthickness=S(3 if active else 1),
                                highlightbackground="#ffffff" if active else hdr)
                card.pack(fill="x", pady=S(5), padx=S(2))
                tk.Frame(card, bg=hdr, height=S(5)).pack(fill="x")
                row = tk.Frame(card, bg=bg)
                row.pack(fill="x", padx=S(8), pady=S(8))
                photo = self._slot_photo(slot, S(64))
                if photo is not None:
                    photos.append(photo)
                    pic = tk.Label(row, image=photo, bg=bg, bd=0)
                else:
                    pic = tk.Label(row, text=(slot["name"][:1] or "?").upper(), bg=hdr, fg=hdr_fg,
                                   font=("Sans", 20, "bold"), width=3)
                pic.pack(side="left", padx=(0, S(10)))
                text_box = tk.Frame(row, bg=bg)
                text_box.pack(side="left", fill="x", expand=True)
                clickable = [card, row, pic, text_box]
                name_l = tk.Label(text_box, text=slot["name"], bg=bg, fg=fg, font=("Sans", 11, "bold"), anchor="w")
                name_l.pack(fill="x")
                clickable.append(name_l)
                if slot.get("description"):
                    desc_l = tk.Label(text_box, text=slot["description"], bg=bg, fg=fg, font=("Sans", 9),
                                      anchor="w", justify="left", wraplength=S(200))
                    desc_l.pack(fill="x")
                    clickable.append(desc_l)
                model = slot["providers"].get(slot["provider"], {}).get("model", "")
                info_l = tk.Label(text_box, text=f"{slot['provider']} \u00b7 {model}", bg=bg, fg=sub,
                                  font=("Sans", 8), anchor="w", justify="left", wraplength=S(200))
                info_l.pack(fill="x")
                clickable.append(info_l)
                side = tk.Frame(row, bg=bg)
                side.pack(side="right", padx=(S(6), 0))
                tk.Button(side, text="In use" if active else "Use", bg=btn, fg=btn_fg,
                          activebackground=shade(btn, -0.15), activeforeground=btn_fg, relief="flat",
                          padx=S(10), command=lambda i=i: use(i)).pack(fill="x")
                tk.Button(side, text="Edit", bg=shade(bg, 0.2 if dark else -0.12), fg=fg,
                          activebackground=shade(bg, 0.3 if dark else -0.2), activeforeground=fg,
                          relief="flat", padx=S(10), command=lambda i=i: edit(i)).pack(fill="x", pady=(S(4), 0))
                for w in clickable:
                    w.bind("<Button-1>", lambda _e, i=i: use(i))
            add_btn.config(state="disabled" if len(self.cfg["slots"]) >= MAX_SLOTS else "normal")

        render()
        self._slots_close = close
        win.bind("<Escape>", close)
        win.protocol("WM_DELETE_WINDOW", close)
        self._show_popup(win)

    def open_slot_editor(self):
        """Edit the slot in use: name, description, photo and colors (all other settings: 'All settings')."""
        if self.slot_edit_win is not None and self.slot_edit_win.winfo_exists():
            self.slot_edit_win.lift()
            return
        idx = self.cfg.get("active_slot", 0)
        slot = self.cfg["slots"][idx]
        win = self._popup(480, 620)
        self.slot_edit_win = win
        self._menu_styles(win)
        self._drag_bar(win, f"Edit slot {idx + 1}")
        orig_colors = {k: self.cfg[k] for k in COLOR_KEYS}  # restored if you cancel
        photo_data = [slot.get("photo", "")]
        preview_ref = []

        btns = tk.Frame(win, bg=MENU_BG)
        btns.pack(side="bottom", pady=S(10))
        body = ttk.Frame(win, style="S.TFrame", padding=S(14))
        body.pack(fill="both", expand=True)

        def hint(row, text, color=MENU_HINT):
            return tk.Label(body, text=text, bg=MENU_BG, fg=color, font=("Sans", 8), anchor="w",
                            justify="left", wraplength=S(400))

        name_var = tk.StringVar(value=slot["name"])
        desc_var = tk.StringVar(value=slot.get("description", ""))

        def limit(var, n):
            def cut(*_):
                if len(var.get()) > n:
                    var.set(var.get()[:n])
            var.trace_add("write", cut)

        limit(name_var, 24)
        limit(desc_var, 70)
        ttk.Label(body, text="Name", style="S.TLabel").grid(row=0, column=0, sticky="w", pady=S(4))
        ttk.Entry(body, textvariable=name_var, width=30).grid(row=0, column=1, columnspan=3, sticky="w", pady=S(4))
        ttk.Label(body, text="Description", style="S.TLabel").grid(row=1, column=0, sticky="w", pady=S(4))
        ttk.Entry(body, textvariable=desc_var, width=30).grid(row=1, column=1, columnspan=3, sticky="w", pady=S(4))

        # ----- photo -----
        ttk.Label(body, text="Photo", style="S.TLabel").grid(row=2, column=0, sticky="nw", pady=S(10))
        photo_box = tk.Frame(body, bg=MENU_BG)
        photo_box.grid(row=2, column=1, columnspan=3, sticky="w", pady=S(8))
        preview = tk.Label(photo_box, bg=MENU_TAB, fg=MENU_HINT, text="no photo", width=10, height=4)
        preview.pack(side="left")
        photo_btns = tk.Frame(photo_box, bg=MENU_BG)
        photo_btns.pack(side="left", padx=S(10))
        photo_msg = tk.Label(body, bg=MENU_BG, fg=MENU_ERR, font=("Sans", 8), anchor="w", justify="left",
                             wraplength=S(400))
        photo_msg.grid(row=3, column=0, columnspan=4, sticky="w")

        def refresh_preview():
            img = self._slot_photo({"photo": photo_data[0]}, S(64))
            del preview_ref[:]
            if img is not None:
                preview_ref.append(img)
                preview.config(image=img, text="", width=0, height=0)
            else:
                preview.config(image="", text="no photo", width=10, height=4)

        def choose_photo():
            win.attributes("-topmost", False)  # so the file picker is not hidden behind this menu
            try:
                path = filedialog.askopenfilename(
                    parent=win, title="Choose a photo for this slot",
                    filetypes=[("Pictures", "*.png *.jpg *.jpeg *.gif *.bmp *.webp"), ("All files", "*.*")])
            finally:
                try:
                    win.attributes("-topmost", True)
                    win.lift()
                except tk.TclError:
                    pass
            if not path:
                return
            data, error = load_slot_photo(path)
            photo_msg.config(text=error)
            if data:
                photo_data[0] = data
                refresh_preview()

        def remove_photo():
            photo_data[0] = ""
            photo_msg.config(text="")
            refresh_preview()

        ttk.Button(photo_btns, text="Choose photo...", command=choose_photo).pack(anchor="w")
        ttk.Button(photo_btns, text="Remove photo", command=remove_photo).pack(anchor="w", pady=(S(4), 0))
        refresh_preview()

        # ----- colors (they change the window right away; Cancel puts them back) -----
        color_vars = {}
        applying = [False]
        _now = tuple(str(self.cfg[k]).lower() for k in COLOR_KEYS)
        preset_var = tk.StringVar(value=next((n for n, c in THEMES.items() if c == _now), "Custom colors"))

        def on_manual():
            if applying[0]:
                return
            cur = tuple(color_vars[k].get().strip().lower() for k in COLOR_KEYS)
            if not all(HEX_RE.match(c) for c in cur):
                return
            applying[0] = True
            preset_var.set(next((n for n, c in THEMES.items() if c == cur), "Custom colors"))
            applying[0] = False

        def color_row(row, text, key):
            var = tk.StringVar(value=self.cfg[key])
            color_vars[key] = var
            ttk.Label(body, text=text, style="S.TLabel").grid(row=row, column=0, sticky="w", pady=S(4))
            ttk.Entry(body, textvariable=var, width=9).grid(row=row, column=1, sticky="w", pady=S(4))
            swatch = tk.Label(body, width=3, bg=var.get(), relief="solid", bd=1)
            swatch.grid(row=row, column=2, padx=S(6))

            def pick():
                cur = var.get() if HEX_RE.match(var.get()) else DEFAULTS[key]
                win.attributes("-topmost", False)
                try:
                    _rgb, chosen = colorchooser.askcolor(color=cur, parent=win, title=text)
                finally:
                    try:
                        win.attributes("-topmost", True)
                        win.lift()
                    except tk.TclError:
                        pass
                if chosen:
                    var.set(chosen)

            ttk.Button(body, text="Pick...", width=7, command=pick).grid(row=row, column=3, sticky="w")

            def changed(*_):
                c = var.get().strip()
                if HEX_RE.match(c):
                    swatch.config(bg=c)
                    self.cfg[key] = c
                    self.apply_theme()
                    on_manual()
            var.trace_add("write", changed)

        color_row(4, "Background color", "bg_color")
        color_row(5, "Top bar color", "header_color")
        color_row(6, "Send button color", "button_color")
        ttk.Label(body, text="Color preset", style="S.TLabel").grid(row=7, column=0, sticky="w", pady=S(4))
        choice_box(body, preset_var, ["Custom colors"] + list(THEMES), 20).grid(row=7, column=1, columnspan=3,
                                                                                 sticky="w", pady=S(4))

        def on_preset(*_):
            preset = THEMES.get(preset_var.get())
            if applying[0] or not preset:
                return
            applying[0] = True
            for k, v in zip(COLOR_KEYS, preset):
                color_vars[k].set(v)
            applying[0] = False

        preset_var.trace_add("write", on_preset)
        hint(8, "Every setting is saved per slot (AI, look, window, keys, typing, screenshot, fun). "
                "Use 'All settings' to change them for this slot.").grid(
            row=8, column=0, columnspan=4, sticky="w", pady=(S(10), 0))

        def finish(save, then=None):
            self._edit_cancel = None
            if save:
                slot["name"] = name_var.get().strip() or f"Slot {idx + 1}"
                slot["description"] = desc_var.get().strip()
                slot["photo"] = photo_data[0]
            else:
                for k, v in orig_colors.items():
                    self.cfg[k] = v
                self.apply_theme()
            self.slot_edit_win = None
            try:
                win.destroy()
            except tk.TclError:
                pass
            self.update_title()
            save_config(self.cfg)  # also copies the colors into this slot
            if then:
                then()

        confirm = [None]

        def disarm():
            confirm[0] = None
            try:
                del_btn.config(text="Delete slot", bg=MENU_BUTTON, activebackground=MENU_BUTTON_ACTIVE)
            except tk.TclError:
                pass

        def delete():
            if len(self.cfg["slots"]) <= 1:
                photo_msg.config(text="You need at least one slot, so this one can't be deleted.")
                return
            if confirm[0] is None:  # two clicks in a row, so it can't happen by accident
                del_btn.config(text="Click again to delete", bg=MENU_QUIT, activebackground="#d33a54")
                confirm[0] = win.after(4000, disarm)
                return
            win.after_cancel(confirm[0])
            disarm()
            self._edit_cancel = None
            del self.cfg["slots"][idx]
            apply_slot(self.cfg, max(0, idx - 1))
            self.slot_edit_win = None
            win.destroy()
            self.apply_theme()
            self.update_title()
            save_config(self.cfg)
            self.open_slots()

        def flat_button(text, command, color=MENU_BUTTON, active=MENU_BUTTON_ACTIVE):
            b = tk.Button(btns, text=text, bg=color, fg=MENU_FG, activebackground=active,
                          activeforeground=MENU_FG, relief="flat", padx=S(12), command=command)
            b.pack(side="left", padx=4)
            return b

        flat_button("Save", lambda: finish(True, self.open_slots))
        flat_button("All settings", lambda: finish(True, self.open_settings))
        del_btn = flat_button("Delete slot", delete)
        flat_button("Cancel", lambda: finish(False, self.open_slots))

        self._edit_cancel = lambda: finish(False)
        win.bind("<Escape>", lambda _e: finish(False, self.open_slots))
        win.protocol("WM_DELETE_WINDOW", lambda: finish(False, self.open_slots))
        self._show_popup(win)

    # ---------- settings menu ----------
    def open_settings(self):
        if self.settings_win is not None and self.settings_win.winfo_exists():
            self.settings_win.lift()
            return
        win = self._popup(580, 640)
        self.settings_win = win
        self._menu_styles(win)
        _slots_t = self.cfg.get("slots") or []
        _name_t = _slots_t[self.cfg.get("active_slot", 0)]["name"] if _slots_t else ""
        self._drag_bar(win, f"Settings  (saved in slot: {_name_t})")

        def choice(parent, var, values, width):
            """Pick-from-a-list box with arrow buttons. A drop-down list can stay open and block the
            hotkeys if you click away from it, so this one deliberately has no pop-up."""
            return ttk.Spinbox(parent, textvariable=var, values=list(values), state="readonly",
                               width=width, wrap=True)

        nb = ttk.Notebook(win)  # (packed below, after the buttons, so the buttons always stay visible)
        canvases = {}

        def new_tab(name):
            """A tab whose content scrolls when the screen is too small to show all of it."""
            outer = ttk.Frame(nb, style="S.TFrame")
            canvas = tk.Canvas(outer, bg=MENU_BG, highlightthickness=0, bd=0)
            bar = ttk.Scrollbar(outer, orient="vertical", command=canvas.yview)
            canvas.configure(yscrollcommand=bar.set)
            inner = ttk.Frame(canvas, style="S.TFrame", padding=12)
            item = canvas.create_window((0, 0), window=inner, anchor="nw")

            def refresh(_e=None):
                canvas.configure(scrollregion=canvas.bbox("all"))
                canvas.itemconfigure(item, width=canvas.winfo_width())
                need = inner.winfo_reqheight() > canvas.winfo_height()
                if need and not bar.winfo_ismapped():
                    bar.pack(side="right", fill="y", before=canvas)
                elif not need and bar.winfo_ismapped():
                    bar.pack_forget()
                    canvas.yview_moveto(0)

            inner.bind("<Configure>", refresh)
            canvas.bind("<Configure>", refresh)
            canvas.pack(side="left", fill="both", expand=True)
            nb.add(outer, text=name)
            canvases[str(outer)] = canvas
            inner.tab_id = outer  # so nb.select(inner.tab_id) can switch to this tab
            return inner

        def on_wheel(ev):
            cv = canvases.get(nb.select())
            if cv is not None and cv.yview() != (0.0, 1.0):
                cv.yview_scroll(-1 if (getattr(ev, "num", 0) == 4 or getattr(ev, "delta", 0) > 0) else 1, "units")

        for seq in ("<Button-4>", "<Button-5>", "<MouseWheel>"):
            win.bind(seq, on_wheel)

        t_ai, t_look, t_win, t_keys, t_type, t_shot, t_fun = (new_tab("AI"), new_tab("Look"), new_tab("Window"),
                                                              new_tab("Keybinds"), new_tab("Typing"),
                                                              new_tab("Screenshot"), new_tab("Fun"))

        # ================= AI tab =================
        prov_state = copy.deepcopy(self.cfg["providers"])
        current = [self.cfg["provider"]]
        prov_var = tk.StringVar(value=current[0])
        key_var = tk.StringVar(value=prov_state[current[0]]["api_key"])
        model_var = tk.StringVar(value=prov_state[current[0]]["model"])

        def section_of(provider):
            return LOGIN_SECTION if provider in NO_KEY_NEEDED else API_SECTION

        mode_var = tk.StringVar(value=section_of(current[0]))
        ttk.Label(t_ai, text="Connection", style="S.TLabel").grid(row=0, column=0, sticky="w", pady=4)
        mode_combo = choice(t_ai, mode_var, [LOGIN_SECTION, API_SECTION], 24)
        mode_combo.grid(row=0, column=1, pady=4)
        ttk.Label(t_ai, text="Provider", style="S.TLabel").grid(row=1, column=0, sticky="w", pady=4)
        prov_combo = choice(t_ai, prov_var, SECTION_PROVIDERS[mode_var.get()], 24)
        prov_combo.grid(row=1, column=1, pady=4)
        ttk.Label(t_ai, text="API key", style="S.TLabel").grid(row=2, column=0, sticky="w", pady=4)
        key_entry = ttk.Entry(t_ai, textvariable=key_var, show="\u2022", width=27)
        key_entry.grid(row=2, column=1, pady=4)
        ttk.Label(t_ai, text="Model", style="S.TLabel").grid(row=3, column=0, sticky="w", pady=4)
        ttk.Entry(t_ai, textvariable=model_var, width=27).grid(row=3, column=1, pady=4)

        hint = tk.Label(t_ai, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left", wraplength=S(340))
        hint.grid(row=7, column=0, columnspan=2, sticky="w", pady=(6, 0))
        shot_var = tk.StringVar(value=self.cfg.get("screenshot_prompt", DEFAULTS["screenshot_prompt"]))
        ttk.Label(t_ai, text="Screenshot prompt", style="S.TLabel").grid(row=4, column=0, sticky="w", pady=4)
        ttk.Entry(t_ai, textvariable=shot_var, width=27).grid(row=4, column=1, pady=4)

        auto_var = tk.BooleanVar(value=bool(self.cfg.get("auto_prompt_enabled", False)))
        auto_text_var = tk.StringVar(value=self.cfg.get("auto_prompt", ""))
        ttk.Checkbutton(t_ai, text="Auto prompt: send it to the AI when the program starts",
                        variable=auto_var, style="S.TCheckbutton").grid(row=5, column=0, columnspan=2,
                                                                         sticky="w", pady=(10, 2))
        ttk.Label(t_ai, text="Auto prompt", style="S.TLabel").grid(row=6, column=0, sticky="w", pady=4)
        ttk.Entry(t_ai, textvariable=auto_text_var, width=27).grid(row=6, column=1, pady=4)

        persona_var = tk.StringVar(value=self.cfg.get("persona", "Default")
                                   if self.cfg.get("persona", "Default") in PERSONAS else "Default")
        custom_persona_var = tk.StringVar(value=self.cfg.get("custom_persona", ""))
        ttk.Label(t_ai, text="Persona", style="S.TLabel").grid(row=8, column=0, sticky="w", pady=(12, 4))
        choice(t_ai, persona_var, list(PERSONAS), 24).grid(row=8, column=1, pady=(12, 4))
        ttk.Label(t_ai, text="Custom persona", style="S.TLabel").grid(row=9, column=0, sticky="w", pady=4)
        ttk.Entry(t_ai, textvariable=custom_persona_var, width=27).grid(row=9, column=1, pady=4)
        persona_hint = tk.Label(t_ai, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w",
                                justify="left", wraplength=S(340))
        persona_hint.grid(row=10, column=0, columnspan=2, sticky="w", pady=(2, 0))

        def refresh_persona_hint(*_):
            name = persona_var.get()
            if name == "Custom":
                persona_hint.config(text="Type your own instruction in 'Custom persona', for example: "
                                         "\"Always answer in Catalan, in two sentences.\"")
            elif name == "Default":
                persona_hint.config(text="No extra instruction: the AI answers normally.")
            else:
                persona_hint.config(text="Hidden instruction sent with every question: " + PERSONAS.get(name, ""))
        persona_var.trace_add("write", refresh_persona_hint)
        refresh_persona_hint()
        _slots_now = self.cfg.get("slots") or []
        _slot_name = _slots_now[self.cfg.get("active_slot", 0)]["name"] if _slots_now else ""
        tk.Label(t_ai, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left",
                 wraplength=S(340),
                 text=f"Every setting in this menu is saved in the slot in use ({_slot_name}), so each slot can "
                      f"be a totally different setup. Switch slots with {label('settings')}.").grid(row=11, column=0, columnspan=2,
                                                                      sticky="w", pady=(S(10), 0))

        def refresh_hint():
            p = current[0]
            if p in CLI_TOOLS:
                hint.config(text=f"{CLI_TOOLS[p]['install']} {CLI_TOOLS[p]['note']} "
                                 "No API key is used. Screenshots are not supported here.")
            elif p in NO_KEY_NEEDED:
                hint.config(text="Runs on your own computer, no login or key. Install Ollama first "
                                 "(ollama.com). For screenshots use a vision model such as llama3.2-vision.")
            else:
                hint.config(text=f"Needs an API key. Or set env var {PROVIDERS[p]['env']}.")
            key_entry.configure(state="disabled" if p in NO_KEY_NEEDED else "normal")
        refresh_hint()

        def on_mode_change(*_):
            values = SECTION_PROVIDERS[mode_var.get()]
            prov_combo.configure(values=values)
            if prov_var.get() not in values:
                prov_var.set(values[0])  # triggers on_provider_change below
        mode_var.trace_add("write", on_mode_change)

        def on_provider_change(_e=None):
            prov_state[current[0]] = {"api_key": "".join(key_var.get().split()), "model": model_var.get().strip()}
            current[0] = prov_var.get()
            key_var.set(prov_state[current[0]]["api_key"])
            model_var.set(prov_state[current[0]]["model"])
            refresh_hint()

        prov_var.trace_add("write", lambda *_: on_provider_change())

        # ================= Look tab =================
        title_var = tk.StringVar(value=self.cfg["title"])
        corner_var = tk.StringVar(value=self.cfg["corner"])
        vars_ = {k: tk.IntVar(value=self.cfg[k]) for k in ("offset_x", "offset_y", "width", "height")}
        color_vars = {}

        ttk.Label(t_look, text="Window name", style="S.TLabel").grid(row=0, column=0, sticky="w", pady=4)
        ttk.Entry(t_look, textvariable=title_var, width=28).grid(row=0, column=1, columnspan=3,
                                                                  sticky="w", pady=4)

        def apply_title(*_):
            self.cfg["title"] = title_var.get().strip() or DEFAULTS["title"]
            self.update_title()
        title_var.trace_add("write", apply_title)

        COLOR_KEYS = ("bg_color", "header_color", "button_color")
        applying = [False]  # True while a preset is being applied (so it is not taken for a manual edit)
        _now = tuple(str(self.cfg.get(k, "")).lower() for k in COLOR_KEYS)
        _saved = self.cfg.get("custom_colors")
        custom_saved = ([str(c).lower() for c in _saved] if isinstance(_saved, list) and len(_saved) == 3
                        and all(HEX_RE.match(str(c)) for c in _saved) else list(DEFAULTS["custom_colors"]))
        _preset_now = next((n for n, c in THEMES.items() if c == _now), None)
        if _preset_now is None and all(HEX_RE.match(c) for c in _now):
            custom_saved[:] = _now  # the colors you use now are your custom look
        theme_var = tk.StringVar(value=_preset_now or "Custom colors")

        def on_manual_color_change():
            """You changed a color yourself: switch the preset box to 'Custom colors' (or to the preset
            these colors happen to match) and remember them as your custom look."""
            if applying[0]:
                return
            cur = tuple(color_vars[k].get().strip().lower() for k in COLOR_KEYS)
            if not all(HEX_RE.match(c) for c in cur):
                return
            name = next((n for n, c in THEMES.items() if c == cur), None)
            if name is None:
                custom_saved[:] = cur
                name = "Custom colors"
            applying[0] = True
            theme_var.set(name)
            applying[0] = False

        def color_row(row, text, cfg_key):
            var = tk.StringVar(value=self.cfg[cfg_key])
            color_vars[cfg_key] = var
            ttk.Label(t_look, text=text, style="S.TLabel").grid(row=row, column=0, sticky="w", pady=4)
            ttk.Entry(t_look, textvariable=var, width=9).grid(row=row, column=1, sticky="w", pady=4)
            swatch = tk.Label(t_look, width=3, bg=var.get(), relief="solid", bd=1)
            swatch.grid(row=row, column=2, padx=6)

            def pick():
                cur = var.get() if HEX_RE.match(var.get()) else DEFAULTS[cfg_key]
                _rgb, chosen = colorchooser.askcolor(color=cur, parent=win, title=text)
                if chosen:
                    var.set(chosen)

            ttk.Button(t_look, text="Pick...", width=7, command=pick).grid(row=row, column=3, sticky="w")

            def changed(*_):
                c = var.get().strip()
                if HEX_RE.match(c):
                    swatch.config(bg=c)
                    self.cfg[cfg_key] = c
                    self.apply_theme()
                    on_manual_color_change()
            var.trace_add("write", changed)

        color_row(1, "Background color", "bg_color")
        color_row(2, "Top bar color", "header_color")
        color_row(3, "Send button color", "button_color")

        ttk.Label(t_look, text="Theme preset", style="S.TLabel").grid(row=4, column=0, sticky="w", pady=4)
        choice(t_look, theme_var, ["Custom colors"] + list(THEMES), 20).grid(row=4, column=1, columnspan=3,
                                                                             sticky="w", pady=4)

        def apply_theme_preset(*_):
            if applying[0]:
                return
            name = theme_var.get()
            preset = THEMES.get(name) or (tuple(custom_saved) if name == "Custom colors" else None)
            if preset:
                applying[0] = True
                for cfg_key, value in zip(COLOR_KEYS, preset):
                    color_vars[cfg_key].set(value)
                applying[0] = False
        theme_var.trace_add("write", apply_theme_preset)

        # ----- Window tab: corner, size, exact X/Y, frameless -----
        ttk.Label(t_win, text="Screen corner", style="S.TLabel").grid(row=0, column=0, sticky="w", pady=4)
        corner_combo = choice(t_win, corner_var, CORNERS, 16)
        corner_combo.grid(row=0, column=1, columnspan=2, sticky="w", pady=4)

        rows = [("Offset X (px)", "offset_x", 0, 5000), ("Offset Y (px)", "offset_y", 0, 5000),
                ("Width (px)", "width", 200, 3000), ("Height (px)", "height", 150, 3000)]
        for i, (text, key, lo, hi) in enumerate(rows, start=1):
            ttk.Label(t_win, text=text, style="S.TLabel").grid(row=i, column=0, sticky="w", pady=4)
            ttk.Spinbox(t_win, from_=lo, to=hi, increment=10, textvariable=vars_[key],
                        width=10).grid(row=i, column=1, sticky="w", pady=4)

        exact_var = tk.BooleanVar(value=bool(self.cfg.get("use_exact_position", False)))
        pos_vars = {"pos_x": tk.IntVar(value=int(self.cfg.get("pos_x", 20))),
                    "pos_y": tk.IntVar(value=int(self.cfg.get("pos_y", 100)))}
        ttk.Checkbutton(t_win, text="Use exact position (X, Y from the top-left of the screen)",
                        variable=exact_var, style="S.TCheckbutton").grid(row=5, column=0, columnspan=3,
                                                                          sticky="w", pady=(12, 2))
        ttk.Label(t_win, text="X (px)", style="S.TLabel").grid(row=6, column=0, sticky="w", pady=4)
        ttk.Spinbox(t_win, from_=-5000, to=20000, increment=10, textvariable=pos_vars["pos_x"],
                    width=10).grid(row=6, column=1, sticky="w", pady=4)
        ttk.Label(t_win, text="Y (px)", style="S.TLabel").grid(row=7, column=0, sticky="w", pady=4)
        ttk.Spinbox(t_win, from_=-5000, to=20000, increment=10, textvariable=pos_vars["pos_y"],
                    width=10).grid(row=7, column=1, sticky="w", pady=4)

        def use_current_position():
            self.root.update_idletasks()
            pos_vars["pos_x"].set(self.root.winfo_x())
            pos_vars["pos_y"].set(self.root.winfo_y())
            exact_var.set(True)

        ttk.Button(t_win, text="Use current window position",
                   command=use_current_position).grid(row=8, column=0, columnspan=2, sticky="w", pady=(4, 2))
        pos_label = tk.Label(t_win, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 9), anchor="w")
        pos_label.grid(row=9, column=0, columnspan=3, sticky="w")

        def refresh_pos_label():
            try:
                if win.winfo_exists():
                    pos_label.config(text=f"Window is now at X={self.root.winfo_x()}, Y={self.root.winfo_y()}")
                    win.after(300, refresh_pos_label)
            except tk.TclError:
                pass
        refresh_pos_label()

        frameless_var = tk.BooleanVar(value=bool(self.cfg.get("frameless", False)))
        ttk.Checkbutton(t_win, text="Frameless window (no title bar, close / minimize / maximize)",
                        variable=frameless_var, style="S.TCheckbutton").grid(row=10, column=0, columnspan=3,
                                                                              sticky="w", pady=(14, 2))
        tk.Label(t_win, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left", wraplength=S(360),
                 text=f"Drag the window by its colored top bar to move it. Close it with {label('toggle')}. "
                      "For the best result install xprop (sudo apt install x11-utils). If typing in the "
                      "window stops working, turn this off."
                 ).grid(row=11, column=0, columnspan=3, sticky="w")

        def frameless_changed(*_):
            self.cfg["frameless"] = bool(frameless_var.get())
            self.apply_frameless()
        frameless_var.trace_add("write", frameless_changed)

        _scale_now = str(self.cfg.get("ui_scale", "auto")).strip()
        scale_var = tk.StringVar(value=_scale_now if _scale_now in SCALE_CHOICES else "Auto")
        ttk.Label(t_win, text="Interface size", style="S.TLabel").grid(row=12, column=0, sticky="w",
                                                                         pady=(S(14), 4))
        choice(t_win, scale_var, SCALE_CHOICES, 10).grid(row=12, column=1, sticky="w", pady=(S(14), 4))
        tk.Label(t_win, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left",
                 wraplength=S(360),
                 text="Makes the window and the menus bigger on high-resolution screens. 'Auto' picks a size "
                      "for your screen. Applies the next time you start the program."
                 ).grid(row=13, column=0, columnspan=3, sticky="w")

        opacity_var = tk.IntVar(value=int(round(float(self.cfg.get("opacity", 1.0)) * 100)))

        def apply_opacity_live(*_):
            try:
                self.cfg["opacity"] = round(min(100, max(10, int(opacity_var.get()))) / 100, 2)
            except (tk.TclError, ValueError):
                return
            self.apply_opacity()

        ttk.Label(t_look, text="Opacity (%)", style="S.TLabel").grid(row=9, column=0, sticky="w", pady=4)
        tk.Scale(t_look, from_=10, to=100, orient="horizontal", variable=opacity_var, length=S(170), sliderlength=S(30), width=S(15),
                 bg=MENU_BG, fg=MENU_FG, troughcolor=MENU_TAB, highlightthickness=0, bd=0,
                 command=apply_opacity_live).grid(row=9, column=1, columnspan=3, sticky="w", pady=2)
        tk.Label(t_look, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left", wraplength=S(360),
                 text="100 = solid, lower = more see-through (text fades too). Minimum 10%."
                 ).grid(row=10, column=0, columnspan=4, sticky="w")

        font_var = tk.IntVar(value=int(self.cfg.get("font_size", DEFAULTS["font_size"])))

        def apply_font_live(*_):
            try:
                self.cfg["font_size"] = min(24, max(7, int(font_var.get())))
            except (tk.TclError, ValueError):
                return
            self.apply_theme()

        ttk.Label(t_look, text="Text size", style="S.TLabel").grid(row=11, column=0, sticky="w", pady=(10, 4))
        tk.Scale(t_look, from_=7, to=24, orient="horizontal", variable=font_var, length=S(170), sliderlength=S(30), width=S(15),
                 bg=MENU_BG, fg=MENU_FG, troughcolor=MENU_TAB, highlightthickness=0, bd=0,
                 command=apply_font_live).grid(row=11, column=1, columnspan=3, sticky="w", pady=(8, 2))
        tk.Label(t_look, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left", wraplength=S(360),
                 text="Size of the text in the chat, the input box and the Send button (default 10)."
                 ).grid(row=12, column=0, columnspan=4, sticky="w")

        def apply_live(*_):
            try:
                self.cfg["corner"] = corner_var.get()
                for k, v in vars_.items():
                    self.cfg[k] = int(v.get())
                self.cfg["use_exact_position"] = bool(exact_var.get())
                for k, v in pos_vars.items():
                    self.cfg[k] = int(v.get())
            except (tk.TclError, ValueError):
                return
            self.apply_geometry()

        corner_var.trace_add("write", apply_live)
        for v in vars_.values():
            v.trace_add("write", apply_live)
        exact_var.trace_add("write", apply_live)
        for v in pos_vars.values():
            v.trace_add("write", apply_live)

        # ================= Keybinds tab =================
        key_vars = {a: tk.StringVar(value=self.cfg["keys"][a]) for a in ACTION_LABELS}
        mod_vars = {m: tk.BooleanVar(value=(m in self.cfg["modifiers"])) for m in MOD_ORDER}

        ttk.Label(t_keys, text="Hold these keys together with the key:", style="S.TLabel").grid(
            row=0, column=0, columnspan=2, sticky="w")
        mod_row = ttk.Frame(t_keys, style="S.TFrame")
        mod_row.grid(row=1, column=0, columnspan=2, sticky="w", pady=(2, 10))
        for m in MOD_ORDER:
            ttk.Checkbutton(mod_row, text=MOD_LABELS[m], variable=mod_vars[m],
                            style="S.TCheckbutton").pack(side="left", padx=(0, 10))

        for i, action in enumerate(ACTION_LABELS, start=2):
            ttk.Label(t_keys, text=ACTION_LABELS[action], style="S.TLabel").grid(row=i, column=0,
                                                                                  sticky="w", pady=4)
            ttk.Spinbox(t_keys, textvariable=key_vars[action], values=ALLOWED_KEYS, width=6,
                        wrap=True).grid(row=i, column=1, sticky="w", pady=4, padx=(10, 0))

        keys_msg = tk.Label(t_keys, bg=MENU_BG, fg=MENU_ERR, font=("Sans", 9), anchor="w",
                            justify="left", wraplength=S(360))
        keys_msg.grid(row=12, column=0, columnspan=2, sticky="w", pady=(8, 0))
        tk.Label(t_keys, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left", wraplength=S(360),
                 text="Applied when you click Save. You need at least one modifier, otherwise normal "
                      "typing would be blocked. Emergency quit is always Ctrl+Alt+Shift+Q."
                 ).grid(row=13, column=0, columnspan=2, sticky="w", pady=(4, 0))

        def reset_keys():
            for a, v in key_vars.items():
                v.set(DEFAULT_KEYS[a])
            for m, v in mod_vars.items():
                v.set(m in DEFAULT_MODIFIERS)
            keys_msg.config(text="")

        ttk.Button(t_keys, text="Reset keybinds", command=reset_keys).grid(row=14, column=0, sticky="w", pady=(10, 0))

        # ================= Typing tab =================
        layout_var = tk.StringVar(value=self.cfg.get("layout", "auto"))
        newline_var = tk.StringVar(value=self.cfg.get("newline_mode", "Shift+Enter"))
        pause_var = tk.BooleanVar(value=bool(self.cfg.get("pause_when_focused", True)))
        delay_var = tk.StringVar(value=f"{float(self.cfg.get('type_delay', TYPE_DELAY)):.2f}")

        ttk.Label(t_type, text="Keyboard layout", style="S.TLabel").grid(row=0, column=0, sticky="w", pady=4)
        choice(t_type, layout_var, ["auto", "us", "es", "other"], 14).grid(row=0, column=1, sticky="w", pady=4)
        ttk.Label(t_type, text="Newlines typed as", style="S.TLabel").grid(row=1, column=0, sticky="w", pady=4)
        choice(t_type, newline_var, ["Shift+Enter", "Enter", "Space"], 14).grid(row=1, column=1, sticky="w", pady=4)
        ttk.Label(t_type, text="Delay between letters (s)", style="S.TLabel").grid(row=2, column=0, sticky="w", pady=4)
        ttk.Spinbox(t_type, from_=0.0, to=5.0, increment=0.01, format="%.2f",
                    textvariable=delay_var, width=12).grid(row=2, column=1, sticky="w", pady=4)
        ttk.Checkbutton(t_type, text="Pause hotkeys while you type in this window\n"
                                     "(lets you type capitals; the open/close key still works)",
                        variable=pause_var, style="S.TCheckbutton").grid(row=3, column=0, columnspan=2,
                                                                          sticky="w", pady=(10, 4))
        type_msg = tk.Label(t_type, bg=MENU_BG, fg=MENU_ERR, font=("Sans", 9), anchor="w",
                            justify="left", wraplength=S(360))
        type_msg.grid(row=4, column=0, columnspan=2, sticky="w")
        tk.Label(t_type, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left", wraplength=S(360),
                 text=f"{label('type')} types the last answer letter by letter. Press Esc to stop it. "
                      "The delay is the pause between letters (default 0.05 s; 0 = as fast as possible, "
                      "but some apps may drop letters if it is too low). 'auto' detects your keyboard "
                      "layout; use 'other' if letters come out wrong (slower, but always correct). "
                      "'Newlines typed as Shift+Enter' avoids sending chat messages by accident."
                 ).grid(row=5, column=0, columnspan=2, sticky="w", pady=(8, 0))

        # ================= Screenshot tab =================
        MODE_LABELS = {"area": "Select area", "full": "Whole screen (silent)", "off": "Off"}
        MODE_BY_LABEL = {v: k for k, v in MODE_LABELS.items()}
        tool_var = tk.StringVar(value=self.cfg.get("screenshot_tool", "auto"))
        mode1_var = tk.StringVar(value=MODE_LABELS.get(self.cfg.get("screenshot_mode", "area"), "Select area"))
        mode2_var = tk.StringVar(value=MODE_LABELS.get(self.cfg.get("screenshot2_mode", "full"),
                                                       "Whole screen (silent)"))

        ttk.Label(t_shot, text="Screenshot program", style="S.TLabel").grid(row=0, column=0, sticky="w", pady=4)
        choice(t_shot, tool_var, SCREENSHOT_TOOLS, 18).grid(row=0, column=1, sticky="w", pady=4)
        tk.Label(t_shot, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left", wraplength=S(400),
                 text="'auto' tries the programs installed on your system one after another, which can open "
                      "more than one screenshot app if the first one fails. Pick a specific program here "
                      "(flameshot, gnome-screenshot, portal = your desktop's built-in one, ...) and ONLY that "
                      "one will ever be used."
                 ).grid(row=1, column=0, columnspan=2, sticky="w", pady=(0, 10))

        ttk.Label(t_shot, text=f"{label('screenshot')} does", style="S.TLabel").grid(row=2, column=0,
                                                                                      sticky="w", pady=4)
        choice(t_shot, mode1_var, list(MODE_LABELS.values()), 22).grid(row=2, column=1, sticky="w", pady=4)
        ttk.Label(t_shot, text=f"{label('screenshot2')} does", style="S.TLabel").grid(row=3, column=0,
                                                                                       sticky="w", pady=4)
        choice(t_shot, mode2_var, list(MODE_LABELS.values()), 22).grid(row=3, column=1, sticky="w", pady=4)
        tk.Label(t_shot, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left", wraplength=S(400),
                 text="Select area: drag a rectangle, then confirm. Whole screen (silent): the AI window hides "
                      "for a moment, the whole screen is captured and sent right away with no selection. "
                      "Set one key to each to have both. The keys themselves can be changed in the Keybinds tab."
                 ).grid(row=4, column=0, columnspan=2, sticky="w", pady=(10, 0))

        keep_focus_var = tk.BooleanVar(value=bool(self.cfg.get("screenshot_keep_focus", DEFAULTS["screenshot_keep_focus"])))
        ttk.Checkbutton(t_shot, text="Keep my focus after a screenshot\n"
                                     "(don't jump into the AI window's text box)",
                        variable=keep_focus_var, style="S.TCheckbutton").grid(row=5, column=0, columnspan=2,
                                                                               sticky="w", pady=(14, 2))
        tk.Label(t_shot, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left", wraplength=S(400),
                 text="On: the AI window is only made invisible for the screenshot and then comes back "
                      "without taking the keyboard, so you keep typing in the app you were in. If the window "
                      "was closed it stays closed (open it with the open/close key, or use the paste / type "
                      "keys to get the answer). Off: the window opens after every screenshot."
                 ).grid(row=6, column=0, columnspan=2, sticky="w")

        # ================= Fun tab =================
        horse_var = tk.BooleanVar(value=bool(self.cfg.get("fun_horse", False)))
        bounce_var = tk.BooleanVar(value=bool(self.cfg.get("horse_bounce", True)))
        horse_size_var = tk.IntVar(value=int(self.cfg.get("horse_size", DEFAULTS["horse_size"])))
        pirate_var = tk.BooleanVar(value=bool(self.cfg.get("fun_pirate", False)))
        pirate_size_var = tk.IntVar(value=int(self.cfg.get("pirate_size", DEFAULTS["pirate_size"])))
        _side_now = self.cfg.get("pirate_side", DEFAULTS["pirate_side"])
        pirate_side_var = tk.StringVar(value=_side_now if _side_now in PIRATE_SIDES else DEFAULTS["pirate_side"])
        pirate_lift_var = tk.IntVar(value=int(self.cfg.get("pirate_lift", 0)))
        scare_var = tk.BooleanVar(value=bool(self.cfg.get("jumpscare_enabled", False)))
        scare_min_var = tk.IntVar(value=int(self.cfg.get("jumpscare_min", DEFAULTS["jumpscare_min"])))
        scare_max_var = tk.IntVar(value=int(self.cfg.get("jumpscare_max", DEFAULTS["jumpscare_max"])))

        def fun_scale(parent, lo, hi, var):
            return tk.Scale(parent, from_=lo, to=hi, orient="horizontal", variable=var, length=S(170),
                            sliderlength=S(30), width=S(15), bg=MENU_BG, fg=MENU_FG, troughcolor=MENU_TAB,
                            highlightthickness=0, bd=0)

        # --- the spinning horse ---
        ttk.Checkbutton(t_fun, text="Fun horse: show a spinning horse on my screen", variable=horse_var,
                        style="S.TCheckbutton").grid(row=0, column=0, columnspan=3, sticky="w", pady=(0, 4))
        ttk.Checkbutton(t_fun, text="Bounce around the screen", variable=bounce_var,
                        style="S.TCheckbutton").grid(row=1, column=0, columnspan=3, sticky="w", padx=(20, 0))
        ttk.Label(t_fun, text="Horse size", style="S.TLabel").grid(row=2, column=0, sticky="w", padx=(20, 0), pady=4)
        fun_scale(t_fun, 80, 300, horse_size_var).grid(row=2, column=1, columnspan=2, sticky="w", pady=2)
        tk.Label(t_fun, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left", wraplength=S(400),
                 text="Click the horse to make it spin the other way. Untick the box to make it go away."
                 ).grid(row=3, column=0, columnspan=3, sticky="w", padx=(20, 0))

        ttk.Separator(t_fun, orient="horizontal").grid(row=4, column=0, columnspan=3, sticky="ew", pady=14)

        # --- the pirate ---
        ttk.Checkbutton(t_fun, text="Pirate: show the company pirate at the bottom of my screen",
                        variable=pirate_var, style="S.TCheckbutton").grid(row=5, column=0, columnspan=3,
                                                                            sticky="w", pady=(0, 4))
        ttk.Label(t_fun, text="Pirate size", style="S.TLabel").grid(row=6, column=0, sticky="w", padx=(20, 0), pady=4)
        fun_scale(t_fun, 80, 400, pirate_size_var).grid(row=6, column=1, columnspan=2, sticky="w", pady=2)
        pirate_row = ttk.Frame(t_fun, style="S.TFrame")
        pirate_row.grid(row=7, column=0, columnspan=3, sticky="w", padx=(20, 0), pady=4)
        ttk.Label(pirate_row, text="Stand on the", style="S.TLabel").pack(side="left")
        choice(pirate_row, pirate_side_var, PIRATE_SIDES, 8).pack(side="left", padx=4)
        ttk.Label(pirate_row, text="of the screen, lifted", style="S.TLabel").pack(side="left")
        ttk.Spinbox(pirate_row, from_=0, to=600, increment=10, textvariable=pirate_lift_var,
                    width=5).pack(side="left", padx=4)
        ttk.Label(pirate_row, text="px", style="S.TLabel").pack(side="left")
        tk.Label(t_fun, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left", wraplength=S(400),
                 text="The pirate keeps waving along the bottom edge of the screen. Lift it a bit if a taskbar "
                      "covers its feet. (On Linux the horse and the pirate sit on a box in your window's "
                      "background color.)"
                 ).grid(row=8, column=0, columnspan=3, sticky="w", padx=(20, 0))

        ttk.Separator(t_fun, orient="horizontal").grid(row=9, column=0, columnspan=3, sticky="ew", pady=14)

        # --- the random jump scare ---
        ttk.Checkbutton(t_fun, text="Random jump scare: the dog pops up on your screen", variable=scare_var,
                        style="S.TCheckbutton").grid(row=10, column=0, columnspan=3, sticky="w", pady=(0, 4))
        scare_row = ttk.Frame(t_fun, style="S.TFrame")
        scare_row.grid(row=11, column=0, columnspan=3, sticky="w", padx=(20, 0), pady=4)
        ttk.Label(scare_row, text="At a random moment between", style="S.TLabel").pack(side="left")
        ttk.Spinbox(scare_row, from_=1, to=600, textvariable=scare_min_var, width=4).pack(side="left", padx=4)
        ttk.Label(scare_row, text="and", style="S.TLabel").pack(side="left")
        ttk.Spinbox(scare_row, from_=1, to=600, textvariable=scare_max_var, width=4).pack(side="left", padx=4)
        ttk.Label(scare_row, text="minutes", style="S.TLabel").pack(side="left")
        ttk.Button(t_fun, text="Test jump scare (in 2 seconds)",
                   command=lambda: self.root.after(2000, self.show_jumpscare)).grid(
            row=12, column=0, columnspan=3, sticky="w", padx=(20, 0), pady=(6, 2))
        tk.Label(t_fun, bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8), anchor="w", justify="left", wraplength=S(400),
                 text="It shows for a couple of seconds and goes away by itself, or click it to close it. "
                      "The timer starts again after every scare and only runs while this program is running. "
                      "For a bigger, smoother picture install: sudo apt install python3-pil.imagetk"
                 ).grid(row=13, column=0, columnspan=3, sticky="w", padx=(20, 0))

        def horse_toggled(*_):
            try:
                self.cfg["fun_horse"] = bool(horse_var.get())
            except tk.TclError:
                return
            if self.cfg["fun_horse"]:
                self.start_horse()
            else:
                self.stop_horse()

        def bounce_changed(*_):
            try:
                self.cfg["horse_bounce"] = bool(bounce_var.get())
            except tk.TclError:
                pass

        size_job = [None]

        def horse_size_changed(*_):
            try:
                self.cfg["horse_size"] = min(300, max(80, int(horse_size_var.get())))
            except (tk.TclError, ValueError):
                return
            if size_job[0] is not None:
                self.root.after_cancel(size_job[0])
            if self.horse:  # redraw with the new size once you stop dragging
                size_job[0] = self.root.after(250, self.start_horse)

        pirate_job = [None]

        def pirate_changed(*_):
            try:
                self.cfg["fun_pirate"] = bool(pirate_var.get())
                self.cfg["pirate_size"] = min(400, max(80, int(pirate_size_var.get())))
                self.cfg["pirate_side"] = pirate_side_var.get() if pirate_side_var.get() in PIRATE_SIDES else "Right"
                self.cfg["pirate_lift"] = min(600, max(0, int(pirate_lift_var.get())))
            except (tk.TclError, ValueError):
                return
            if pirate_job[0] is not None:
                self.root.after_cancel(pirate_job[0])

            def apply_pirate():
                pirate_job[0] = None
                if self.cfg["fun_pirate"]:
                    self.start_pirate()
                else:
                    self.stop_pirate()
            pirate_job[0] = self.root.after(250, apply_pirate)  # once you stop dragging / typing

        def scare_changed(*_):
            try:
                self.cfg["jumpscare_enabled"] = bool(scare_var.get())
                lo = max(1, int(scare_min_var.get()))
                hi = max(lo, int(scare_max_var.get()))
                self.cfg["jumpscare_min"], self.cfg["jumpscare_max"] = lo, hi
            except (tk.TclError, ValueError):
                return
            self.schedule_jumpscare()

        horse_var.trace_add("write", horse_toggled)
        bounce_var.trace_add("write", bounce_changed)
        horse_size_var.trace_add("write", horse_size_changed)
        for v in (pirate_var, pirate_size_var, pirate_side_var, pirate_lift_var):
            v.trace_add("write", pirate_changed)
        scare_var.trace_add("write", scare_changed)
        scare_min_var.trace_add("write", scare_changed)
        scare_max_var.trace_add("write", scare_changed)

        # ================= buttons =================
        def read_keybinds():
            mods = [m for m in MOD_ORDER if mod_vars[m].get()]
            if not mods:
                return None, None, "Pick at least one modifier (Shift, Ctrl, Alt or Super)."
            keys = {a: v.get().strip().upper() for a, v in key_vars.items()}
            for a, k in keys.items():
                if k not in ALLOWED_KEYS:
                    return None, None, f"'{k}' is not a valid key. Use A-Z, 0-9 or F1-F12."
            if len(set(keys.values())) != len(keys):
                return None, None, "Two actions use the same key. Give each action its own key."
            return keys, mods, ""

        def save_and_close():
            keys, mods, error = read_keybinds()
            if error:
                nb.select(t_keys.tab_id)
                keys_msg.config(text=error)
                return
            try:
                type_delay = float(delay_var.get().replace(",", "."))  # accepts 0,05 too
                if not 0 <= type_delay <= 5:
                    raise ValueError
            except ValueError:
                nb.select(t_type.tab_id)
                type_msg.config(text="Delay must be a number between 0 and 5 seconds.")
                return
            apply_live()
            apply_title()
            prov_state[current[0]] = {"api_key": "".join(key_var.get().split()), "model": model_var.get().strip()}
            for name in prov_state:
                if not prov_state[name]["model"]:
                    prov_state[name]["model"] = PROVIDERS[name]["model"]
            self.cfg["providers"] = prov_state
            self.cfg["provider"] = current[0]
            self.cfg["layout"] = layout_var.get()
            self.cfg["newline_mode"] = newline_var.get()
            self.cfg["type_delay"] = type_delay
            self.cfg["screenshot_prompt"] = shot_var.get().strip() or DEFAULTS["screenshot_prompt"]
            self.cfg["screenshot_tool"] = tool_var.get()
            self.cfg["screenshot_mode"] = MODE_BY_LABEL.get(mode1_var.get(), "area")
            self.cfg["screenshot2_mode"] = MODE_BY_LABEL.get(mode2_var.get(), "full")
            self.cfg["screenshot_keep_focus"] = bool(keep_focus_var.get())
            self.cfg["persona"] = persona_var.get() if persona_var.get() in PERSONAS else "Default"
            self.cfg["custom_persona"] = custom_persona_var.get().strip()
            self.cfg["custom_colors"] = list(custom_saved)
            self.cfg["auto_prompt_enabled"] = bool(auto_var.get())
            self.cfg["auto_prompt"] = auto_text_var.get().strip()
            self.cfg["ui_scale"] = "auto" if scale_var.get() == "Auto" else scale_var.get()
            apply_opacity_live()
            self.cfg["pause_when_focused"] = bool(pause_var.get())
            if keys != self.cfg["keys"] or mods != self.cfg["modifiers"]:
                self.cfg["keys"], self.cfg["modifiers"] = keys, mods
                self.apply_keybinds()
                self.append("sys", f"Keybinds updated: {label('toggle')} open/close · {label('ask')} ask · "
                                   f"{label('screenshot')} / {label('screenshot2')} screenshot · {label('paste')} paste · {label('type')} type · "
                                   f"{label('settings')} menu · {label('quit')} quit\n\n")
            self.update_title()
            save_config(self.cfg)
            self._settings_save = None
            win.destroy()
            self.settings_win = None

        confirm_job = [None]

        def disarm_reset():
            """Put the Reset button back to normal (the second click did not come in time, or it was used)."""
            confirm_job[0] = None
            try:
                reset_btn.config(text="Reset everything", bg=MENU_BUTTON, activebackground=MENU_BUTTON_ACTIVE)
            except tk.TclError:
                pass

        def reset_everything():
            """Put EVERY setting on every tab back to its default. Needs two clicks in a row so it can't
            happen by accident (no pop-up window on purpose, a pop-up could steal focus from the hotkeys)."""
            if confirm_job[0] is None:
                reset_btn.config(text="Click again to erase ALL", bg=MENU_QUIT, activebackground="#d33a54")
                confirm_job[0] = win.after(4000, disarm_reset)
                return
            win.after_cancel(confirm_job[0])
            disarm_reset()

            # ---- AI tab (this also wipes the saved API keys and models) ----
            mode_var.set(section_of(DEFAULTS["provider"]))
            prov_var.set(DEFAULTS["provider"])
            for name in prov_state:
                prov_state[name] = {"api_key": "", "model": PROVIDERS[name]["model"]}
            key_var.set("")
            model_var.set(PROVIDERS[current[0]]["model"])
            shot_var.set(DEFAULTS["screenshot_prompt"])
            auto_var.set(DEFAULTS["auto_prompt_enabled"])
            auto_text_var.set(DEFAULTS["auto_prompt"])
            persona_var.set("Default")
            custom_persona_var.set(DEFAULTS["custom_persona"])

            # ---- Look tab ----
            title_var.set(DEFAULTS["title"])
            custom_saved[:] = DEFAULTS["custom_colors"]
            theme_var.set("Default purple")
            opacity_var.set(int(round(DEFAULTS["opacity"] * 100)))
            apply_opacity_live()
            font_var.set(DEFAULTS["font_size"])
            apply_font_live()

            # ---- Window tab ----
            corner_var.set(DEFAULTS["corner"])
            for k, v in vars_.items():
                v.set(DEFAULTS[k])
            exact_var.set(DEFAULTS["use_exact_position"])
            for k, v in pos_vars.items():
                v.set(DEFAULTS[k])
            frameless_var.set(DEFAULTS["frameless"])
            apply_live()

            # ---- Keybinds tab ----
            reset_keys()

            # ---- Typing tab ----
            layout_var.set(DEFAULTS["layout"])
            newline_var.set(DEFAULTS["newline_mode"])
            delay_var.set(f"{DEFAULTS['type_delay']:.2f}")
            pause_var.set(DEFAULTS["pause_when_focused"])
            type_msg.config(text="")

            # ---- Screenshot tab ----
            tool_var.set(DEFAULTS["screenshot_tool"])
            mode1_var.set(MODE_LABELS[DEFAULTS["screenshot_mode"]])
            mode2_var.set(MODE_LABELS[DEFAULTS["screenshot2_mode"]])
            keep_focus_var.set(DEFAULTS["screenshot_keep_focus"])

            # ---- Fun tab (turning these off also stops the horse / jump scare right away) ----
            horse_var.set(DEFAULTS["fun_horse"])
            bounce_var.set(DEFAULTS["horse_bounce"])
            horse_size_var.set(DEFAULTS["horse_size"])
            scare_var.set(DEFAULTS["jumpscare_enabled"])
            scare_min_var.set(DEFAULTS["jumpscare_min"])
            scare_max_var.set(DEFAULTS["jumpscare_max"])
            pirate_var.set(DEFAULTS["fun_pirate"])
            pirate_size_var.set(DEFAULTS["pirate_size"])
            pirate_side_var.set(DEFAULTS["pirate_side"])
            pirate_lift_var.set(DEFAULTS["pirate_lift"])

            # ---- Window tab: interface size ----
            scale_var.set("Auto")

            # ---- Save slots: three fresh ones (this erases their names, photos and keys too) ----
            self.cfg["slots"] = default_slots()
            self.cfg["active_slot"] = 0
            self.update_title()

        btns = tk.Frame(win, bg=MENU_BG)
        btns.pack(side="bottom", pady=10)
        nb.pack(fill="both", expand=True, padx=8, pady=(8, 0))
        tk.Button(btns, text="Save", bg=MENU_BUTTON, fg=MENU_FG, activebackground=MENU_BUTTON_ACTIVE,
                  activeforeground=MENU_FG, relief="flat", padx=12,
                  command=save_and_close).pack(side="left", padx=4)
        reset_btn = tk.Button(btns, text="Reset everything", bg=MENU_BUTTON, fg=MENU_FG,
                              activebackground=MENU_BUTTON_ACTIVE, activeforeground=MENU_FG, relief="flat",
                              padx=12, command=reset_everything)
        reset_btn.pack(side="left", padx=4)
        tk.Button(btns, text="Quit app", bg=MENU_QUIT, fg="white", activebackground="#d33a54",
                  activeforeground="white", relief="flat", padx=12,
                  command=lambda: (save_and_close(), self.quit_app())).pack(side="left", padx=4)

        self._settings_save = save_and_close
        win.protocol("WM_DELETE_WINDOW", save_and_close)
        win.bind("<Escape>", lambda _e: save_and_close())
        tk.Label(win, text="Made by Invis", bg=MENU_BG, fg=MENU_HINT, font=("Sans", 8)).place(
            relx=1.0, rely=1.0, x=-10, y=-6, anchor="se")
        self._show_popup(win)

    # ---------- main loop ----------
    def run(self):
        print(f"Running. {label('toggle')} open/close · "
              f"{label('settings')} settings · {label('ask')} ask about highlighted text · "
              f"{label('screenshot')} / {label('screenshot2')} screenshot · {label('paste')} paste answer · {label('type')} type answer · "
              f"{label('quit')} quit · Ctrl+Alt+Shift+Q emergency quit")

        def on_term(*_):
            self.engine.shutdown()
            os._exit(0)

        signal.signal(signal.SIGTERM, on_term)
        try:
            self.root.mainloop()
        except KeyboardInterrupt:
            pass
        finally:
            self.engine.shutdown()
            os._exit(0)  # also stops the device threads so the keyboard is released


